INSERT INTO `categories` VALUES (1,'Lãng mạn','lang-man','Thể loại lãng mạn tình cảm ngọt ngào hoặc trắc trở.','2026-06-04 07:44:06'),(2,'Fanfiction','fanfiction','Truyện đồng nhân, viết về thần tượng, nhân vật hư cấu có sẵn.','2026-06-04 07:44:06'),(3,'Truyện Ngắn','truyen-ngan','Các câu chuyện ngắn gọn, súc tích.','2026-06-04 07:44:06'),(4,'Tiểu Thuyết Chung','tieu-thuyet-chung','Tiểu thuyết tổng hợp với nhiều chủ đề khác nhau.','2026-06-04 07:44:06'),(5,'Ngẫu nhiên','ngau-nhien','Những chia sẻ ngẫu hứng, nhật ký hoặc nội dung tự do.','2026-06-04 07:44:06'),(6,'Hài hước','hai-huoc','Câu chuyện đem lại tiếng cười và sự giải trí.','2026-06-04 07:44:06'),(7,'Tiểu Thuyết Thiếu Niên','tieu-thuyet-thieu-nien','Những câu chuyện tuổi học trò, thanh xuân vườn trường.','2026-06-04 07:44:06'),(8,'Viễn tưởng','vien-tuong','Thế giới tưởng tượng, kỳ ảo và ma thuật.','2026-06-04 07:44:06'),(9,'Phi Tiểu Thuyết','phi-tieu-thuyet','Hồi ký, tản văn.','2026-06-04 07:44:06'),(10,'Kinh dị','kinh-di','Những câu chuyện rùng rợn, đáng sợ.','2026-06-04 07:44:06'),(11,'Bí ẩn','bi-an','Giải quyết các vụ án, bí ẩn chưa có lời giải.','2026-06-04 07:44:06'),(12,'Thriller','thriller','Kịch tính, giật gân, đấu trí căng thẳng.','2026-06-04 07:44:06'),(13,'Phiêu lưu','phieu-luu','Hành trình khám phá những vùng đất mới.','2026-06-04 07:44:06'),(14,'Tiểu Thuyết Lịch Sử','tieu-thuyet-lich-su','Lấy bối cảnh thời kỳ lịch sử có thật hoặc giả tưởng lịch sử.','2026-06-04 07:44:06'),(15,'Siêu nhiên','sieu-nhien','Các hiện tượng kỳ bí vượt ngoài thế giới tự nhiên.','2026-06-04 07:44:06'),(16,'Ma cà rồng','ma-ca-rong','Thể loại ma cà rồng đầy cuốn hút và bí ẩn.','2026-06-04 07:44:06'),(17,'Truyện Tâm Linh','truyen-tam-linh','Khám phá thế giới tâm linh, huyền bí.','2026-06-04 07:44:06'),(18,'ChickLit','chicklit','Truyện dành riêng cho phụ nữ hiện đại, hài hước lãng mạn.','2026-06-04 07:44:06'),(19,'Thơ Ca','tho-ca','Sáng tác thơ ca, vần điệu cảm xúc.','2026-06-04 07:44:06'),(20,'Người sói','nguoi-soi','Những câu chuyện thần thoại về người sói.','2026-06-04 07:44:06'),(21,'Cổ điển','co-dien','Văn học mang màu sắc cổ điển, có giá trị lâu dài.','2026-06-04 07:44:06');
