LOCK TABLES `chapters` WRITE;
/*!40000 ALTER TABLE `chapters` DISABLE KEYS */;
INSERT INTO `chapters` VALUES (136,22,'CHƯƠNG 1: VŨ KHÚC - PHÁ QUÂN',1,'<p><em style=\"color: rgb(255, 255, 255);\">&quot;Vũ&nbsp;Khúc&nbsp;là&nbsp;tài&nbsp;tinh,&nbsp;chủ&nbsp;về&nbsp;tiền&nbsp;tài,&nbsp;ý&nbsp;chí&nbsp;và&nbsp;sự&nbsp;tích&nbsp;lũy.&nbsp;Nhưng&nbsp;khi&nbsp;đi&nbsp;cùng&nbsp;Phá&nbsp;Quân&nbsp;–&nbsp;một&nbsp;sao&nbsp;của&nbsp;biến&nbsp;động,&nbsp;phá&nbsp;cách&nbsp;và&nbsp;tái&nbsp;sinh&nbsp;–&nbsp;thì&nbsp;mọi&nbsp;thứ&nbsp;không&nbsp;còn&nbsp;là&nbsp;con&nbsp;đường&nbsp;thẳng.&nbsp;Đó&nbsp;là&nbsp;một&nbsp;canh&nbsp;bạc:&nbsp;hoặc&nbsp;thành&nbsp;công&nbsp;rực&nbsp;rỡ,&nbsp;hoặc&nbsp;tự&nbsp;tay&nbsp;đập&nbsp;nát&nbsp;tất&nbsp;cả&nbsp;để&nbsp;làm&nbsp;lại&nbsp;từ&nbsp;đầu.&quot;</em></p><p></p><p><span style=\"color: rgb(255, 255, 255);\">Trời&nbsp;tháng&nbsp;sáu,&nbsp;nắng&nbsp;lặng&nbsp;lẽ&nbsp;tràn&nbsp;xuống,&nbsp;len&nbsp;vào&nbsp;từng&nbsp;con&nbsp;hẻm&nbsp;nhỏ,&nbsp;phủ&nbsp;lên&nbsp;những&nbsp;bức&nbsp;tường&nbsp;cũ&nbsp;một&nbsp;lớp&nbsp;ánh&nbsp;sáng&nbsp;trong&nbsp;veo&nbsp;mà&nbsp;bỏng&nbsp;rát&nbsp;như&nbsp;thủy&nbsp;tinh&nbsp;đang&nbsp;âm&nbsp;thầm&nbsp;tan&nbsp;chảy.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ngôi&nbsp;chùa&nbsp;nép&nbsp;mình&nbsp;trong&nbsp;một&nbsp;con&nbsp;hẻm&nbsp;ngoằn&nbsp;ngoèo,&nbsp;tường&nbsp;vàng&nbsp;bong&nbsp;tróc&nbsp;từng&nbsp;mảng,&nbsp;mái&nbsp;ngói&nbsp;rêu&nbsp;phong&nbsp;sẫm&nbsp;màu&nbsp;theo&nbsp;năm&nbsp;tháng.&nbsp;Khói&nbsp;hương&nbsp;quẩn&nbsp;quanh,&nbsp;lặng&nbsp;lẽ&nbsp;bò&nbsp;lên&nbsp;từng&nbsp;bức&nbsp;tượng,&nbsp;qua&nbsp;những&nbsp;khe&nbsp;gỗ&nbsp;cũ&nbsp;kỹ,&nbsp;rồi&nbsp;tan&nbsp;ra&nbsp;trong&nbsp;thứ&nbsp;ánh&nbsp;sáng&nbsp;đục&nbsp;ngầu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đứng&nbsp;giữa&nbsp;sân&nbsp;chùa,&nbsp;mồ&nbsp;hôi&nbsp;chảy&nbsp;dọc&nbsp;sống&nbsp;lưng,&nbsp;tay&nbsp;chắp&nbsp;trước&nbsp;ngực&nbsp;mà&nbsp;lòng&nbsp;lại&nbsp;loạn&nbsp;như&nbsp;một&nbsp;bản&nbsp;vẽ&nbsp;chưa&nbsp;kịp&nbsp;kẻ&nbsp;lưới.&nbsp;Gương&nbsp;mặt&nbsp;cậu&nbsp;còn&nbsp;giữ&nbsp;nét&nbsp;mềm&nbsp;mại&nbsp;của&nbsp;một&nbsp;sinh&nbsp;viên&nbsp;vừa&nbsp;tốt&nbsp;nghiệp,&nbsp;nhưng&nbsp;trong&nbsp;ánh&nbsp;mắt&nbsp;đã&nbsp;thấp&nbsp;thoáng&nbsp;thứ&nbsp;gì&nbsp;đó&nbsp;rất&nbsp;mỏi.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;mỏi&nbsp;vì&nbsp;tương&nbsp;lai&nbsp;đã&nbsp;vội&nbsp;bắt&nbsp;đầu&nbsp;mà&nbsp;chưa&nbsp;kịp&nbsp;tìm&nbsp;thấy&nbsp;ánh&nbsp;sáng,&nbsp;mỏi&nbsp;vì&nbsp;nhận&nbsp;ra&nbsp;rằng&nbsp;ngay&nbsp;cả&nbsp;ước&nbsp;mơ&nbsp;cũng&nbsp;có&nbsp;hạn&nbsp;sử&nbsp;dụng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Khói&nbsp;hương&nbsp;làm&nbsp;mắt&nbsp;cậu&nbsp;cay&nbsp;xè.&nbsp;Jimin&nbsp;nhắm&nbsp;chặt&nbsp;mắt,&nbsp;thành&nbsp;khẩn&nbsp;cố&nbsp;chấp,&nbsp;như&nbsp;thể&nbsp;nếu&nbsp;cầu&nbsp;thêm&nbsp;một&nbsp;lần&nbsp;nữa,&nbsp;trời&nbsp;cao&nbsp;sẽ&nbsp;mềm&nbsp;lòng&nbsp;mà&nbsp;cho&nbsp;cậu&nbsp;một&nbsp;đặc&nbsp;ân.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bên&nbsp;cạnh,&nbsp;Taehyung&nbsp;cũng&nbsp;chắp&nbsp;tay.&nbsp;Nhưng&nbsp;nếu&nbsp;nhìn&nbsp;kỹ,&nbsp;sẽ&nbsp;thấy&nbsp;cậu&nbsp;ta&nbsp;đang&nbsp;lén&nbsp;hé&nbsp;một&nbsp;mắt&nbsp;ra&nbsp;nhìn&nbsp;xung&nbsp;quanh,&nbsp;giống&nbsp;hệt&nbsp;khách&nbsp;du&nbsp;lịch&nbsp;lạc&nbsp;vào&nbsp;một&nbsp;nơi&nbsp;linh&nbsp;thiêng&nbsp;mà&nbsp;không&nbsp;biết&nbsp;nên&nbsp;diễn&nbsp;thế&nbsp;nào&nbsp;cho&nbsp;hợp&nbsp;vai.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;lẩm&nbsp;bẩm&nbsp;trong&nbsp;miệng:</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cầu&nbsp;cho&nbsp;con&nbsp;có&nbsp;việc&nbsp;làm...Cầu&nbsp;cho&nbsp;con&nbsp;có&nbsp;tiền...&nbsp;Nam&nbsp;Mô&nbsp;A&nbsp;Di&nbsp;Đà&nbsp;Phật...&nbsp;Cầu&nbsp;cho&nbsp;con&nbsp;có&nbsp;công&nbsp;danh...&nbsp;Cầu&nbsp;cho&nbsp;con&nbsp;không&nbsp;bị&nbsp;đời&nbsp;quật&nbsp;ngã&nbsp;ngay&nbsp;khi&nbsp;vừa&nbsp;chạm&nbsp;ngõ...&nbsp;Nam&nbsp;Mô&nbsp;A&nbsp;Di&nbsp;Đà&nbsp;Phật....&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chắp&nbsp;tay&nbsp;lạy&nbsp;thêm&nbsp;ba&nbsp;cái,&nbsp;Jimin&nbsp;suy&nbsp;nghĩ&nbsp;một&nbsp;hồi&nbsp;rồi&nbsp;lại&nbsp;nhắm&nbsp;mắt&nbsp;khấn&nbsp;tiếp:</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cầu&nbsp;cho&nbsp;con&nbsp;có&nbsp;tất&nbsp;cả&nbsp;trừ&nbsp;vất&nbsp;vả....&nbsp;Cầu&nbsp;cho&nbsp;con&nbsp;không&nbsp;làm&nbsp;mà&nbsp;vẫn&nbsp;có&nbsp;ăn...&nbsp;Cầu&nbsp;cho..&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Jimin!&nbsp;Jimin!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;huých&nbsp;một&nbsp;cú&nbsp;nhẹ&nbsp;vào&nbsp;sườn&nbsp;Jimin,&nbsp;giọng&nbsp;thì&nbsp;thầm&nbsp;nhưng&nbsp;đầy&nbsp;phấn&nbsp;khích.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Này...&nbsp;cậu&nbsp;nhìn&nbsp;xuống&nbsp;bảng&nbsp;dưới&nbsp;chân&nbsp;tượng&nbsp;đi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;quay&nbsp;sang&nbsp;với&nbsp;ánh&nbsp;mắt&nbsp;đầy&nbsp;cảnh&nbsp;cáo.&nbsp;Taehyung&nbsp;chỉ&nbsp;hất&nbsp;cằm&nbsp;xuống&nbsp;phía&nbsp;dưới&nbsp;bức&nbsp;tượng&nbsp;trước&nbsp;mặt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;tấm&nbsp;bảng&nbsp;nhỏ,&nbsp;chữ&nbsp;đỏ&nbsp;nổi&nbsp;bật&nbsp;trên&nbsp;nền&nbsp;vàng:</span></p><p><em style=\"color: rgb(255, 255, 255);\">&quot;Phật&nbsp;ban&nbsp;phúc&nbsp;sinh&nbsp;sôi,&nbsp;cầu&nbsp;con&nbsp;đàn&nbsp;cháu&nbsp;đống.&quot;</em></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;đứng&nbsp;im&nbsp;vài&nbsp;giây.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Rồi&nbsp;quay&nbsp;sang&nbsp;nhìn&nbsp;Taehyung.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Rồi&nbsp;lại&nbsp;nhìn&nbsp;tượng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;...&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;...&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Không&nbsp;khí&nbsp;thiêng&nbsp;liêng&nbsp;vỡ&nbsp;ra&nbsp;rất&nbsp;khẽ,&nbsp;như&nbsp;một&nbsp;lớp&nbsp;kính&nbsp;bị&nbsp;rạn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;tặc&nbsp;lưỡi&nbsp;lắc&nbsp;đầu:&nbsp;&quot;Có&nbsp;vẻ&nbsp;điền&nbsp;nhầm&nbsp;nguyện&nbsp;vọng&nbsp;rồi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;thở&nbsp;dài:&nbsp;&quot;Tớ&nbsp;cầu&nbsp;công&nbsp;danh&nbsp;cơ...&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ừ,&nbsp;nhưng&nbsp;có&nbsp;vẻ&nbsp;Phật&nbsp;trên&nbsp;kia&nbsp;đang&nbsp;muốn&nbsp;cậu&nbsp;phát&nbsp;triển&nbsp;theo&nbsp;hướng&nbsp;khác.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;thúc&nbsp;lại&nbsp;một&nbsp;cú&nbsp;vào&nbsp;hông&nbsp;Taehyung,&nbsp;rồi&nbsp;choàng&nbsp;vai&nbsp;cậu&nbsp;đi&nbsp;đến&nbsp;bức&nbsp;tượng&nbsp;phật&nbsp;khác&nbsp;để&nbsp;&quot;</span><em style=\"color: rgb(255, 255, 255);\">điền&nbsp;lại&nbsp;nguyện&nbsp;vọng</em><span style=\"color: rgb(255, 255, 255);\">&quot;.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cơ&nbsp;mà,&nbsp;có&nbsp;đại&nbsp;gia&nbsp;cũng&nbsp;được&nbsp;nhỉ?&nbsp;Ông&nbsp;đây&nbsp;cho&nbsp;mấy&nbsp;đứa&nbsp;cậu&nbsp;cùng&nbsp;hưởng&nbsp;phúc.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cái&nbsp;sự&nbsp;lạc&nbsp;quẻ&nbsp;ấy&nbsp;không&nbsp;dừng&nbsp;lại&nbsp;ở&nbsp;đó.&nbsp;Nó&nbsp;theo&nbsp;họ&nbsp;ra&nbsp;khỏi&nbsp;chính&nbsp;điện,&nbsp;lướt&nbsp;qua&nbsp;những&nbsp;bậc&nbsp;thềm&nbsp;đá&nbsp;nóng&nbsp;shầm&nbsp;hập,&nbsp;rồi&nbsp;dừng&nbsp;lại&nbsp;dưới&nbsp;một&nbsp;gốc&nbsp;đa&nbsp;già,&nbsp;nơi&nbsp;lẽ&nbsp;ra&nbsp;phải&nbsp;là&nbsp;chỗ&nbsp;nghỉ&nbsp;chân&nbsp;mát&nbsp;mẻ&nbsp;thanh&nbsp;tịnh,&nbsp;nhưng&nbsp;lại&nbsp;có&nbsp;một&nbsp;lão&nbsp;thầy&nbsp;bói&nbsp;trông&nbsp;còn&nbsp;mệt&nbsp;đời&nbsp;hơn&nbsp;cả&nbsp;hai&nbsp;đứa&nbsp;sinh&nbsp;viên&nbsp;đang&nbsp;thất&nbsp;nghiệp.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Lão&nbsp;ta&nbsp;ngồi&nbsp;bệt&nbsp;trên&nbsp;một&nbsp;tấm&nbsp;chiếu&nbsp;rách,&nbsp;áo&nbsp;sơ&nbsp;mi&nbsp;bạc&nbsp;màu,&nbsp;kính&nbsp;thì&nbsp;gãy&nbsp;mất&nbsp;một&nbsp;bên&nbsp;gọng.&nbsp;Nếu&nbsp;không&nbsp;có&nbsp;cái&nbsp;hộp&nbsp;bài&nbsp;và&nbsp;vài&nbsp;đồng&nbsp;tiền&nbsp;xu&nbsp;bày&nbsp;trước&nbsp;mặt,&nbsp;Jimin&nbsp;thề&nbsp;rằng&nbsp;ông&nbsp;này&nbsp;nhìn&nbsp;giống&nbsp;một&nbsp;kẻ&nbsp;lừa&nbsp;đảo&nbsp;hơn&nbsp;là&nbsp;người&nbsp;&quot;thông&nbsp;thiên&nbsp;văn,&nbsp;tường&nbsp;địa&nbsp;lý&quot;.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Trước&nbsp;mặt&nbsp;là&nbsp;một&nbsp;tấm&nbsp;biển&nbsp;viết&nbsp;nguệch&nbsp;ngoạc:</span></p><p><em style=\"color: rgb(255, 255, 255);\">&quot;Xem&nbsp;mệnh&nbsp;–&nbsp;giá:&nbsp;tờ&nbsp;tiền&nbsp;cao&nbsp;nhất&nbsp;trong&nbsp;ví&nbsp;của&nbsp;bạn.&quot;</em></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Xem&nbsp;không?&quot;&nbsp;Lão&nbsp;ta&nbsp;hỏi,&nbsp;giọng&nbsp;khàn&nbsp;đặc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Không.&quot;&nbsp;Taehyung&nbsp;trả&nbsp;lời&nbsp;ngay.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Có.&quot;&nbsp;Jimin&nbsp;đáp&nbsp;cùng&nbsp;lúc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Hai&nbsp;người&nbsp;quay&nbsp;sang&nbsp;nhìn&nbsp;nhau.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;hạ&nbsp;giọng:&nbsp;&quot;Cậu&nbsp;nhìn&nbsp;xem&nbsp;lão&nbsp;đó&nbsp;giống&nbsp;thầy&nbsp;bói&nbsp;chỗ&nbsp;nào?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Nhưng&nbsp;Jimin&nbsp;không&nbsp;đi,&nbsp;tay&nbsp;mò&nbsp;vào&nbsp;ví&nbsp;tiền&nbsp;trong&nbsp;túi.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;cố&nbsp;kéo&nbsp;tay&nbsp;Jimin.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đi&nbsp;thôi.&nbsp;Lừa&nbsp;đảo&nbsp;là&nbsp;rõ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;vẫn&nbsp;đứng&nbsp;đó.&nbsp;Nhìn&nbsp;cái&nbsp;bảng,&nbsp;rồi&nbsp;nhìn&nbsp;ví&nbsp;tiền&nbsp;của&nbsp;mình,&nbsp;mỏng&nbsp;đến&nbsp;mức&nbsp;có&nbsp;thể&nbsp;dùng&nbsp;làm&nbsp;bookmark.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;giây.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Hai&nbsp;giây.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;bật&nbsp;cười.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đời&nbsp;tớ&nbsp;giờ&nbsp;còn&nbsp;gì&nbsp;để&nbsp;mất&nbsp;đâu.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Có&nbsp;đó.&quot;&nbsp;Taehyung&nbsp;đáp&nbsp;tỉnh&nbsp;bơ.&nbsp;&quot;Tờ&nbsp;tiền&nbsp;cuối&nbsp;cùng.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Nhưng&nbsp;Jimin&nbsp;vẫn&nbsp;rút&nbsp;nó&nbsp;ra.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Tờ&nbsp;tiền&nbsp;duy&nbsp;nhất,&nbsp;sự&nbsp;cứu&nbsp;cánh&nbsp;cuối&nbsp;cùng,&nbsp;niềm&nbsp;hy&nbsp;vọng&nbsp;mong&nbsp;manh&nbsp;giữa&nbsp;lòng&nbsp;thành&nbsp;phố&nbsp;đắt&nbsp;đỏ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;đặt&nbsp;xuống.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;ôm&nbsp;mặt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Lão&nbsp;thầy&nbsp;bói&nbsp;mở&nbsp;to&nbsp;mắt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ông&nbsp;ta&nbsp;không&nbsp;nói&nbsp;gì,&nbsp;chỉ&nbsp;đưa&nbsp;tay&nbsp;sờ&nbsp;tờ&nbsp;tiền,&nbsp;như&nbsp;xác&nbsp;nhận&nbsp;nó&nbsp;là&nbsp;thật,&nbsp;rồi&nbsp;nhét&nbsp;vào&nbsp;túi&nbsp;quần&nbsp;một&nbsp;cách&nbsp;rất&nbsp;thành&nbsp;thạo.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;bật&nbsp;cười:&nbsp;&quot;Chuẩn&nbsp;lừa&nbsp;đảo.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ánh&nbsp;mắt&nbsp;ông&nbsp;ta&nbsp;bỗng&nbsp;nhiên&nbsp;thay&nbsp;đổi.&nbsp;Tay&nbsp;chỉnh&nbsp;đôi&nbsp;kính&nbsp;gãy&nbsp;gọng,&nbsp;hất&nbsp;mặt&nbsp;nhìn&nbsp;Jimin.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Năm&nbsp;sinh&nbsp;tháng&nbsp;đẻ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đọc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Lão&nbsp;thầy&nbsp;bói&nbsp;vẫy&nbsp;cậu&nbsp;lại&nbsp;gần&nbsp;quan&nbsp;sát&nbsp;kĩ&nbsp;gương&nbsp;mặt,&nbsp;rồi&nbsp;lão&nbsp;nhắm&nbsp;mắt&nbsp;bấm&nbsp;tay&nbsp;lẩm&nbsp;nhẩm&nbsp;gì&nbsp;đó&nbsp;trong&nbsp;miệng.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;cơn&nbsp;gió&nbsp;thổi&nbsp;mạnh&nbsp;khiến&nbsp;vài&nbsp;chiếc&nbsp;lá&nbsp;rơi&nbsp;rụng.&nbsp;Khi&nbsp;có&nbsp;một&nbsp;chiếc&nbsp;lá&nbsp;bay&nbsp;lướt&nbsp;qua,&nbsp;chạm&nbsp;nhẹ&nbsp;vào&nbsp;gương&nbsp;mặt&nbsp;Jimin.&nbsp;Lão&nbsp;thầy&nbsp;bói&nbsp;đột&nbsp;ngột&nbsp;mở&nbsp;mắt&nbsp;khiến&nbsp;cả&nbsp;Jimin&nbsp;và&nbsp;Taehyung&nbsp;chốc&nbsp;giật&nbsp;mình.&nbsp;Lão&nbsp;đột&nbsp;nhiên&nbsp;nắm&nbsp;cổ&nbsp;tay&nbsp;cậu,&nbsp;bàn&nbsp;tay&nbsp;khô&nbsp;ráp,&nbsp;lạnh&nbsp;lẽo&nbsp;khiến&nbsp;cậu&nbsp;sởn&nbsp;nhẹ&nbsp;gai&nbsp;ốc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giọng&nbsp;lão&nbsp;ta&nbsp;trầm&nbsp;đi&nbsp;một&nbsp;cách&nbsp;kỳ&nbsp;lạ:</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Hừ,&nbsp;Vũ&nbsp;Khúc&nbsp;gặp&nbsp;Phá&nbsp;Quân.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;nhíu&nbsp;mày.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Có&nbsp;tài.&nbsp;Có&nbsp;chí.&nbsp;Nhưng&nbsp;cũng&nbsp;có&nbsp;cái&nbsp;tật&nbsp;nổi&nbsp;loạn,&nbsp;bốc&nbsp;đồng.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;khẽ&nbsp;&quot;chậc&quot;&nbsp;một&nbsp;tiếng:&nbsp;&quot;Chuẩn&nbsp;quá&nbsp;rồi&nbsp;còn&nbsp;gì.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Nhưng&nbsp;lão&nbsp;thầy&nbsp;bói&nbsp;không&nbsp;dừng&nbsp;lại.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cách&nbsp;cục&nbsp;này...&nbsp;không&nbsp;tệ.&nbsp;Nhưng&nbsp;bị&nbsp;trói&nbsp;đấy.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Trói&nbsp;gì&nbsp;cơ?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Gió&nbsp;lại&nbsp;lần&nbsp;nữa&nbsp;thổi&nbsp;qua,&nbsp;làm&nbsp;lá&nbsp;đa&nbsp;xào&nbsp;xạc.&nbsp;Không&nbsp;khí&nbsp;bỗng&nbsp;dưng&nbsp;lạnh&nbsp;đi&nbsp;một&nbsp;chút.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Bởi&nbsp;Vòng&nbsp;Kim&nbsp;Cô.&quot;&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;lại&nbsp;lần&nbsp;nữa&nbsp;bật&nbsp;cười.&nbsp;&quot;Sang&nbsp;đến&nbsp;Tây&nbsp;Du&nbsp;Kí&nbsp;rồi&nbsp;sao?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cung&nbsp;Phu&nbsp;có&nbsp;Địa&nbsp;Kiếp,&nbsp;lại&nbsp;thêm&nbsp;Thiên&nbsp;Không.&nbsp;Duyên&nbsp;không&nbsp;phải&nbsp;duyên.&nbsp;Nợ&nbsp;mới&nbsp;là&nbsp;nợ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;bắt&nbsp;đầu&nbsp;thấy&nbsp;hơi&nbsp;lạnh&nbsp;chạy&nbsp;dọc&nbsp;sống&nbsp;lưng,&nbsp;dù&nbsp;trời&nbsp;vẫn&nbsp;nóng&nbsp;như&nbsp;đổ&nbsp;lửa.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cẩn&nbsp;thận&nbsp;người&nbsp;có&nbsp;vết&nbsp;sẹo...&nbsp;ở&nbsp;má&nbsp;trái.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ngón&nbsp;tay&nbsp;ông&nbsp;siết&nbsp;chặt&nbsp;cổ&nbsp;tay&nbsp;cậu&nbsp;hơn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Người&nbsp;đó&nbsp;không&nbsp;phải&nbsp;chánh&nbsp;duyên.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;nhịp.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Mà&nbsp;là&nbsp;nghiệp&nbsp;duyên.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Hai&nbsp;nhịp.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Phải&nbsp;trả.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ba&nbsp;nhịp.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Trả&nbsp;bằng...&nbsp;hai&nbsp;năm&nbsp;nồng&nbsp;cháy.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giọng&nbsp;ông&nbsp;ta&nbsp;khàn&nbsp;đi,&nbsp;gần&nbsp;như&nbsp;thì&nbsp;thầm:</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đổi&nbsp;lại...&nbsp;là&nbsp;vạn&nbsp;năm&nbsp;cô&nbsp;liêu.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ông&nbsp;thầy&nbsp;buông&nbsp;tay,&nbsp;rồi&nbsp;ngã&nbsp;lăn&nbsp;ra&nbsp;ngủ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ngủ&nbsp;thật.&nbsp;Ngáy&nbsp;luôn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đứng&nbsp;chết&nbsp;lặng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;cũng&nbsp;đứng&nbsp;chết&nbsp;lặng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;cúi&nbsp;xuống,&nbsp;nhìn&nbsp;kỹ,&nbsp;rồi&nbsp;thở&nbsp;dài:&nbsp;&quot;Ừ,&nbsp;chuẩn&nbsp;quy&nbsp;trình&nbsp;lừa&nbsp;đảo&nbsp;rồi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;vẫn&nbsp;đứng&nbsp;im,&nbsp;cổ&nbsp;tay&nbsp;còn&nbsp;vương&nbsp;lại&nbsp;cảm&nbsp;giác&nbsp;lạnh&nbsp;buốt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Hai&nbsp;năm&nbsp;nồng&nbsp;cháy...&quot;&nbsp;cậu&nbsp;lẩm&nbsp;bẩm.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ừ,&nbsp;cháy&nbsp;khét&nbsp;túi&nbsp;tiền&nbsp;luôn.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;tặc&nbsp;lưỡi&nbsp;một&nbsp;cái.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Chết&nbsp;tiệt.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;kéo&nbsp;cậu&nbsp;đi,&nbsp;không&nbsp;cho&nbsp;kịp&nbsp;suy&nbsp;nghĩ&nbsp;thêm.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đi.&nbsp;Đi&nbsp;ăn&nbsp;kem&nbsp;thôi.&nbsp;Tớ&nbsp;khao.&nbsp;Tớ&nbsp;cần&nbsp;đường&nbsp;để&nbsp;tiêu&nbsp;hóa&nbsp;cái&nbsp;kịch&nbsp;bản&nbsp;ngược&nbsp;luyến&nbsp;vừa&nbsp;rồi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Kem&nbsp;vỉa&nbsp;hè&nbsp;tan&nbsp;nhanh&nbsp;dưới&nbsp;cái&nbsp;nóng.&nbsp;Jimin&nbsp;và&nbsp;Taehyung&nbsp;ngồi&nbsp;trên&nbsp;chiếc&nbsp;ghế&nbsp;nhựa&nbsp;thấp,&nbsp;cầm&nbsp;cây&nbsp;kem&nbsp;dừa&nbsp;vừa&nbsp;ăn&nbsp;vừa&nbsp;nhai&nbsp;lại&nbsp;lời&nbsp;tiên&nbsp;tri.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Vết&nbsp;sẹo&nbsp;má&nbsp;trái...&quot;&nbsp;Taehyung&nbsp;lặp&nbsp;lại,&nbsp;vừa&nbsp;ăn&nbsp;vừa&nbsp;nói&nbsp;&quot;Nghe&nbsp;như&nbsp;nhân&nbsp;vật&nbsp;phim&nbsp;kinh&nbsp;dị.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;cắn&nbsp;một&nbsp;miếng&nbsp;kem&nbsp;to&nbsp;–&nbsp;&quot;Nhưng&nbsp;nếu&nbsp;có&nbsp;đại&nbsp;gia&nbsp;nuôi&nbsp;thật&nbsp;thì...&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;...???&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;...tớ&nbsp;đeo&nbsp;vòng&nbsp;kim&nbsp;cô&nbsp;cũng&nbsp;được.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;suýt&nbsp;sặc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">____________</span></p><p><span style=\"color: rgb(255, 255, 255);\">Gường&nbsp;kỹ&nbsp;túc&nbsp;xá&nbsp;của&nbsp;Jimin&nbsp;là&nbsp;một&nbsp;định&nbsp;nghĩa&nbsp;rất&nbsp;riêng&nbsp;về&nbsp;&quot;nghệ&nbsp;thuật&quot;.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bản&nbsp;vẽ&nbsp;nằm&nbsp;la&nbsp;liệt&nbsp;trên&nbsp;giường.&nbsp;Có&nbsp;cái&nbsp;hoàn&nbsp;chỉnh,&nbsp;có&nbsp;cái&nbsp;chỉ&nbsp;mới&nbsp;là&nbsp;vài&nbsp;nét&nbsp;phác.&nbsp;Vỏ&nbsp;mì&nbsp;tôm&nbsp;nằm&nbsp;cạnh&nbsp;bút&nbsp;chì.&nbsp;Máy&nbsp;tính&nbsp;vẫn&nbsp;sáng,&nbsp;màn&nbsp;hình&nbsp;dừng&nbsp;ở&nbsp;trận&nbsp;Chiến&nbsp;Trường&nbsp;Cổ&nbsp;Đại&nbsp;của&nbsp;tựa&nbsp;game&nbsp;Top&nbsp;Heroes.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Trong&nbsp;màn&nbsp;hình,&nbsp;Park&nbsp;Jimin&nbsp;không&nbsp;phải&nbsp;là&nbsp;một&nbsp;sinh&nbsp;viên&nbsp;vừa&nbsp;ra&nbsp;trường.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;là&nbsp;Thống&nbsp;soái&nbsp;của&nbsp;bang&nbsp;hội&nbsp;top&nbsp;1&nbsp;server&nbsp;–&nbsp;BAN.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Seokjin&nbsp;hyung!&nbsp;Lên&nbsp;tháp&nbsp;trên&nbsp;hướng&nbsp;12&nbsp;giờ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Chi&nbsp;viện&nbsp;đảo&nbsp;nổi&nbsp;nào&nbsp;Yoongi&nbsp;hyung!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ngón&nbsp;tay&nbsp;lướt&nbsp;nhanh&nbsp;trên&nbsp;chuột,&nbsp;ánh&nbsp;mắt&nbsp;sáng&nbsp;lên&nbsp;thứ&nbsp;ánh&nbsp;sáng&nbsp;mà&nbsp;ngoài&nbsp;đời&nbsp;hiếm&nbsp;khi&nbsp;xuất&nbsp;hiện.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ở&nbsp;đây,&nbsp;cậu&nbsp;không&nbsp;cần&nbsp;nỗ&nbsp;lực,&nbsp;chỉ&nbsp;cần&nbsp;chiến&nbsp;thắng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Sau&nbsp;chiến&nbsp;trường&nbsp;ảo&nbsp;khốc&nbsp;liệt&nbsp;kéo&nbsp;dài&nbsp;45&nbsp;phút,&nbsp;Jimin&nbsp;ngã&nbsp;người&nbsp;xuống&nbsp;giường,&nbsp;nhìn&nbsp;lên&nbsp;trần&nbsp;nhà.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Trong&nbsp;khoảnh&nbsp;khắc&nbsp;yên&nbsp;tĩnh&nbsp;hiếm&nbsp;hoi,&nbsp;cậu&nbsp;nghĩ&nbsp;đến&nbsp;quê&nbsp;nhà.&nbsp;Nghĩ&nbsp;đến&nbsp;bố&nbsp;mẹ.&nbsp;Nghĩ&nbsp;đến&nbsp;những&nbsp;cuộc&nbsp;gọi&nbsp;hỏi&nbsp;thăm&nbsp;luôn&nbsp;kết&nbsp;thúc&nbsp;bằng&nbsp;câu:&nbsp;</span><em style=\"color: rgb(255, 255, 255);\">&quot;Cố&nbsp;lên&nbsp;con&nbsp;nhé.&quot;</em></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;không&nbsp;nói&nbsp;với&nbsp;họ&nbsp;rằng&nbsp;cậu&nbsp;sắp&nbsp;hết&nbsp;tiền.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cũng&nbsp;không&nbsp;nói&nbsp;rằng&nbsp;cậu&nbsp;chưa&nbsp;có&nbsp;việc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Tiếng&nbsp;chuông&nbsp;reo&nbsp;lên,&nbsp;cậu&nbsp;chán&nbsp;chường&nbsp;với&nbsp;tay&nbsp;lấy&nbsp;chiếc&nbsp;điện&nbsp;thoại&nbsp;lăn&nbsp;lóc&nbsp;ở&nbsp;góc&nbsp;giường.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chẳng&nbsp;rõ&nbsp;nội&nbsp;dung&nbsp;cuộc&nbsp;điện&nbsp;thoại&nbsp;là&nbsp;gì,&nbsp;chỉ&nbsp;thấy&nbsp;Park&nbsp;Jimin&nbsp;dạ&nbsp;dạ&nbsp;vâng&nbsp;vâng.&nbsp;Sau&nbsp;khi&nbsp;cúp&nbsp;điện&nbsp;thoại,&nbsp;cậu&nbsp;ngồi&nbsp;đấy&nbsp;ngẩn&nbsp;ngơ&nbsp;hồi&nbsp;lâu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Rồi&nbsp;như&nbsp;có&nbsp;gì&nbsp;bị&nbsp;kích&nbsp;nổ,&nbsp;cậu&nbsp;bỗng&nbsp;dưng&nbsp;hét&nbsp;thật&nbsp;to&nbsp;khiến&nbsp;cả&nbsp;phòng&nbsp;ký&nbsp;túc&nbsp;xá&nbsp;đều&nbsp;quay&nbsp;đầu&nbsp;nhìn.&nbsp;Taehyung&nbsp;ở&nbsp;giường&nbsp;đối&nbsp;diện&nbsp;ném&nbsp;chiếc&nbsp;gối&nbsp;về&nbsp;phía&nbsp;cậu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cậu&nbsp;phát&nbsp;điên&nbsp;gì&nbsp;đấy?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;bắt&nbsp;được&nbsp;chiếc&nbsp;gối,&nbsp;ôm&nbsp;vào&nbsp;lòng&nbsp;cười&nbsp;đến&nbsp;quái&nbsp;gỡ.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Đến&nbsp;khi&nbsp;hết&nbsp;sức&nbsp;lực&nbsp;để&nbsp;cười,&nbsp;Jimin&nbsp;ngẩng&nbsp;mặt&nbsp;lên,&nbsp;ném&nbsp;lại&nbsp;chiếc&nbsp;gối&nbsp;cho&nbsp;Taehyung&nbsp;và&nbsp;nói.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;GOLDEN&nbsp;Architecture&nbsp;gọi&nbsp;tớ&nbsp;hẹn&nbsp;ngày&nbsp;mai&nbsp;phỏng&nbsp;vấn.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">_______________________________________</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ngày&nbsp;hôm&nbsp;sau,&nbsp;Jimin&nbsp;đứng&nbsp;trước&nbsp;văn&nbsp;phòng&nbsp;kiến&nbsp;trúc&nbsp;GOLDEN.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Tòa&nbsp;nhà&nbsp;đứng&nbsp;bên&nbsp;bờ&nbsp;sông,&nbsp;kính&nbsp;phủ&nbsp;từ&nbsp;chân&nbsp;lên&nbsp;đến&nbsp;đỉnh,&nbsp;phản&nbsp;chiếu&nbsp;ánh&nbsp;nắng&nbsp;chiều&nbsp;thành&nbsp;những&nbsp;mảng&nbsp;sáng&nbsp;chói&nbsp;lóa.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;công&nbsp;trình&nbsp;hoàn&nbsp;hảo&nbsp;không&nbsp;tì&nbsp;vết.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;hít&nbsp;một&nbsp;hơi&nbsp;thật&nbsp;sâu,&nbsp;ôn&nbsp;lại&nbsp;kiến&nbsp;thức&nbsp;trong&nbsp;đầu&nbsp;một&nbsp;lượt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bỗng&nbsp;điện&nbsp;thoại&nbsp;rung.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung:&nbsp;</span><em style=\"color: rgb(255, 255, 255);\">&quot;</em><span style=\"color: rgb(255, 255, 255);\">Đừng&nbsp;quên&nbsp;check&nbsp;xem&nbsp;gã&nbsp;nào&nbsp;có&nbsp;vết&nbsp;sẹo&nbsp;má&nbsp;trái&nbsp;nhé.</span><em style=\"color: rgb(255, 255, 255);\">&quot;</em></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;tắt&nbsp;máy.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đồ&nbsp;điên.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;được&nbsp;một&nbsp;cô&nbsp;gái&nbsp;trẻ&nbsp;mời&nbsp;vào&nbsp;phòng&nbsp;họp,&nbsp;không&nbsp;giống&nbsp;bất&nbsp;kỳ&nbsp;nơi&nbsp;nào&nbsp;Jimin&nbsp;từng&nbsp;bước&nbsp;vào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;nơi&nbsp;tối&nbsp;giản,&nbsp;gọn&nbsp;gàng.&nbsp;Mùi&nbsp;gỗ&nbsp;đàn&nbsp;hương&nbsp;thoang&nbsp;thoảng&nbsp;trong&nbsp;không&nbsp;khí.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;người&nbsp;đàn&nbsp;ông&nbsp;ngồi&nbsp;ở&nbsp;giữa,&nbsp;đang&nbsp;cúi&nbsp;đầu.&nbsp;Bút&nbsp;chì&nbsp;trong&nbsp;tay&nbsp;di&nbsp;chuyển&nbsp;trên&nbsp;bản&nbsp;vẽ&nbsp;với&nbsp;những&nbsp;nét&nbsp;dứt&nbsp;khoát,&nbsp;chính&nbsp;xác.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;mở&nbsp;miệng&nbsp;xin&nbsp;chào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;không&nbsp;ngẩng&nbsp;lên,&nbsp;không&nbsp;chào,&nbsp;không&nbsp;hỏi,&nbsp;chỉ&nbsp;im&nbsp;lặng&nbsp;làm&nbsp;việc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Sự&nbsp;im&nbsp;lặng&nbsp;kéo&nbsp;dài&nbsp;đến&nbsp;mức&nbsp;Jimin&nbsp;nghe&nbsp;rõ&nbsp;tiếng&nbsp;tim&nbsp;mình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Thình.&nbsp;Thình.&nbsp;Thình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Rồi&nbsp;cuối&nbsp;cùng,&nbsp;người&nbsp;đàn&nbsp;ông&nbsp;đó&nbsp;cũng&nbsp;ngước&nbsp;mặt&nbsp;lên,&nbsp;dùng&nbsp;ánh&nbsp;mắt&nbsp;ra&nbsp;lệnh&nbsp;Jimin&nbsp;ngồi&nbsp;xuống&nbsp;phía&nbsp;đối&nbsp;diện.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Tôi&nbsp;là&nbsp;Jeon&nbsp;Jungkook.&nbsp;Bản&nbsp;vẽ&nbsp;của&nbsp;em&nbsp;tôi&nbsp;đã&nbsp;xem&nbsp;qua.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giọng&nbsp;nói&nbsp;trầm&nbsp;ấm&nbsp;nhưng&nbsp;đầy&nbsp;uy&nbsp;lực.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Màn&nbsp;hình&nbsp;lớn&nbsp;bật&nbsp;lên,&nbsp;mô&nbsp;hình&nbsp;3D&nbsp;hiện&nbsp;ra.&nbsp;Đó&nbsp;là&nbsp;bản&nbsp;vẽ&nbsp;Jimin&nbsp;tự&nbsp;hào&nbsp;nhất.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Khoảng&nbsp;vượt&nbsp;này,&quot;&nbsp;Jungkook&nbsp;lên&nbsp;tiếng,&nbsp;giọng&nbsp;trầm&nbsp;và&nbsp;phẳng,&nbsp;&quot;em&nbsp;giải&nbsp;quyết&nbsp;bằng&nbsp;kết&nbsp;cấu&nbsp;gì?&quot;&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;chớp&nbsp;mắt,&nbsp;bị&nbsp;mất&nbsp;ngờ&nbsp;với&nbsp;câu&nbsp;hỏi&nbsp;này.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Dạ...em..&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Nếu&nbsp;dùng&nbsp;dầm&nbsp;bê&nbsp;tông&nbsp;cốt&nbsp;thép&nbsp;thông&nbsp;thường,&nbsp;nhịp&nbsp;này&nbsp;sẽ&nbsp;vượt&nbsp;quá&nbsp;giới&nbsp;hạn&nbsp;độ&nbsp;võng&nbsp;cho&nbsp;phép.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;mở&nbsp;miệng&nbsp;rồi&nbsp;đóng&nbsp;lại.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Hay&nbsp;em&nbsp;định&nbsp;để&nbsp;nó...&nbsp;bay?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Không&nbsp;một&nbsp;chút&nbsp;mỉa&nbsp;mai,&nbsp;nhưng&nbsp;cũng&nbsp;không&nbsp;có&nbsp;chút&nbsp;khoan&nbsp;nhượng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;lúng&nbsp;túng,&nbsp;từng&nbsp;câu&nbsp;trả&nbsp;lời&nbsp;rơi&nbsp;ra&nbsp;không&nbsp;trọn&nbsp;vẹn.&nbsp;Cậu&nbsp;bỗng&nbsp;thấy&nbsp;cổ&nbsp;họng&nbsp;mình&nbsp;nghẹn&nbsp;lại.&nbsp;Công&nbsp;trình&nbsp;mà&nbsp;cậu&nbsp;từng&nbsp;tự&nbsp;hào,&nbsp;giờ&nbsp;bị&nbsp;lật&nbsp;tung&nbsp;từng&nbsp;lớp,&nbsp;để&nbsp;lộ&nbsp;ra&nbsp;những&nbsp;khoảng&nbsp;trống&nbsp;mà&nbsp;chính&nbsp;cậu&nbsp;cũng&nbsp;chưa&nbsp;từng&nbsp;nhìn&nbsp;thấy.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;giấc&nbsp;mơ,&nbsp;không&nbsp;móng,&nbsp;không&nbsp;trụ,&nbsp;không&nbsp;chịu&nbsp;được&nbsp;trọng&nbsp;lực&nbsp;của&nbsp;chính&nbsp;nó.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;đứng&nbsp;dậy,&nbsp;bước&nbsp;lại&nbsp;gần.&nbsp;Điều&nbsp;đó&nbsp;khiến&nbsp;Jimin&nbsp;cảm&nbsp;thấy&nbsp;khó&nbsp;thở.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;đưa&nbsp;tay&nbsp;rút&nbsp;cây&nbsp;bút&nbsp;chì&nbsp;khỏi&nbsp;tay&nbsp;cậu&nbsp;một&nbsp;cách&nbsp;dễ&nbsp;dàng&nbsp;và&nbsp;nhẹ&nbsp;nhàng,&nbsp;như&nbsp;tước&nbsp;đi&nbsp;thứ&nbsp;duy&nbsp;nhất&nbsp;cậu&nbsp;có&nbsp;thể&nbsp;bám&nbsp;vào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;không&nbsp;lùi&nbsp;lại&nbsp;ngay.&nbsp;Anh&nbsp;đứng&nbsp;sát&nbsp;đến&nbsp;mức&nbsp;mùi&nbsp;gỗ&nbsp;đàn&nbsp;hương&nbsp;lạnh&nbsp;lẽo&nbsp;vây&nbsp;hãm&nbsp;lấy&nbsp;Jimin,&nbsp;khiến&nbsp;cậu&nbsp;cảm&nbsp;giác&nbsp;như&nbsp;mình&nbsp;đang&nbsp;bị&nbsp;một&nbsp;khối&nbsp;kiến&nbsp;trúc&nbsp;khổng&nbsp;lồ&nbsp;đè&nbsp;nặng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bất&nbsp;chợt,&nbsp;đôi&nbsp;bàn&nbsp;tay&nbsp;thon&nbsp;dài&nbsp;đang&nbsp;cầm&nbsp;chiếc&nbsp;bút&nbsp;chì&nbsp;của&nbsp;Jungkook&nbsp;đưa&nbsp;lên.&nbsp;Jungkook&nbsp;dùng&nbsp;đuôi&nbsp;bút&nbsp;chì&nbsp;khẽ&nbsp;gạt&nbsp;lọn&nbsp;tóc&nbsp;mái&nbsp;hơi&nbsp;rối&nbsp;của&nbsp;Jimin&nbsp;sang&nbsp;một&nbsp;bên,&nbsp;để&nbsp;lộ&nbsp;vầng&nbsp;trán&nbsp;trắng&nbsp;sứ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Đôi&nbsp;mắt&nbsp;anh&nbsp;dán&nbsp;chặt&nbsp;lên&nbsp;trên&nbsp;vầng&nbsp;trán&nbsp;Jimin&nbsp;nơi&nbsp;có&nbsp;ba&nbsp;nốt&nbsp;ruồi&nbsp;tạo&nbsp;thành&nbsp;hình&nbsp;tam&nbsp;giác,&nbsp;một&nbsp;trong&nbsp;số&nbsp;đó&nbsp;nằm&nbsp;ở&nbsp;vị&nbsp;trí&nbsp;trùng&nbsp;khớp&nbsp;đến&nbsp;từng&nbsp;milimet&nbsp;với&nbsp;nốt&nbsp;ruồi&nbsp;trên&nbsp;trán&nbsp;anh.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;bị&nbsp;bất&nbsp;ngờ&nbsp;với&nbsp;hành&nbsp;động&nbsp;này,&nbsp;tay&nbsp;bất&nbsp;giác&nbsp;đưa&nbsp;lên&nbsp;chạm&nbsp;vào&nbsp;nơi&nbsp;anh&nbsp;vừa&nbsp;lướt&nbsp;qua,&nbsp;hoang&nbsp;mang&nbsp;tự&nbsp;hỏi&nbsp;rằng&nbsp;có&nbsp;phải&nbsp;mình&nbsp;đã&nbsp;để&nbsp;sót&nbsp;lại&nbsp;dấu&nbsp;vết&nbsp;gì&nbsp;trên&nbsp;đó&nbsp;không.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;vẫn&nbsp;mang&nbsp;một&nbsp;cảm&nbsp;xúc&nbsp;điềm&nbsp;tĩnh,&nbsp;gương&nbsp;mặt&nbsp;anh&nbsp;không&nbsp;thể&nbsp;hiện&nbsp;bất&nbsp;cứ&nbsp;biểu&nbsp;cảm&nbsp;nào&nbsp;nhưng&nbsp;hàng&nbsp;mi&nbsp;khẽ&nbsp;run&nbsp;nhẹ.&nbsp;Rồi&nbsp;anh&nbsp;hạ&nbsp;tay&nbsp;xuống,&nbsp;dùng&nbsp;chiếc&nbsp;bút&nbsp;tước&nbsp;từ&nbsp;tay&nbsp;Jimin&nbsp;vẽ&nbsp;vài&nbsp;kí&nbsp;hiệu&nbsp;lên&nbsp;trên&nbsp;bản&nbsp;vẽ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ở&nbsp;đây,&quot;&nbsp;Jungkook&nbsp;nói,&nbsp;mắt&nbsp;vẫn&nbsp;dán&nbsp;vào&nbsp;bản&nbsp;vẽ&nbsp;&quot;chúng&nbsp;tôi&nbsp;không&nbsp;thiết&nbsp;kế&nbsp;giấc&nbsp;mơ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;đặt&nbsp;bút&nbsp;xuống.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Chúng&nbsp;tôi&nbsp;cần&nbsp;sự&nbsp;thực&nbsp;tế.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Khi&nbsp;bước&nbsp;vào&nbsp;đây,&nbsp;kết&nbsp;cấu&nbsp;duy&nbsp;nhất&nbsp;em&nbsp;phải&nbsp;tuân&nbsp;theo&nbsp;là..&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Dừng&nbsp;lại&nbsp;một&nbsp;nhịp.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Sự&nbsp;hoàn&nbsp;hảo&nbsp;mà&nbsp;tôi&nbsp;lập&nbsp;trình&nbsp;sẵn.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;ngẩng&nbsp;đầu&nbsp;nhìn&nbsp;lên.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Trong&nbsp;khoảnh&nbsp;khắc&nbsp;Jungkook&nbsp;tiến&nbsp;lại&nbsp;gần&nbsp;hơn,&nbsp;cậu&nbsp;nhìn&nbsp;thấy&nbsp;nó.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;vết&nbsp;sẹo&nbsp;nhạt&nbsp;hiện&nbsp;lên&nbsp;dưới&nbsp;ánh&nbsp;nắng&nbsp;chiều,&nbsp;nơi&nbsp;bờ&nbsp;má&nbsp;trái.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Toàn&nbsp;thân&nbsp;cậu&nbsp;giật&nbsp;thót.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Còn&nbsp;nữa,&quot;&nbsp;Jungkook&nbsp;quay&nbsp;lưng,&nbsp;giọng&nbsp;vẫn&nbsp;đều&nbsp;đều,&nbsp;&quot;đừng&nbsp;mang&nbsp;sự&nbsp;hỗn&nbsp;loạn&nbsp;đó&nbsp;vào&nbsp;văn&nbsp;phòng&nbsp;kiến&nbsp;trúc&nbsp;của&nbsp;tôi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;bước.&nbsp;Hai&nbsp;bước.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Tôi&nbsp;ghét&nbsp;nhất&nbsp;những&nbsp;thứ&nbsp;không&nbsp;nằm&nbsp;trong&nbsp;tầm&nbsp;kiểm&nbsp;soát.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cánh&nbsp;cửa&nbsp;khép&nbsp;lại.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đứng&nbsp;một&nbsp;mình&nbsp;giữa&nbsp;căn&nbsp;phòng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bên&nbsp;ngoài,&nbsp;ánh&nbsp;nắng&nbsp;chiếu&nbsp;qua&nbsp;lớp&nbsp;kính&nbsp;dày,&nbsp;biến&nbsp;cả&nbsp;không&nbsp;gian&nbsp;thành&nbsp;một&nbsp;chiếc&nbsp;lồng&nbsp;sáng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Trong&nbsp;đầu&nbsp;cậu,&nbsp;giọng&nbsp;lão&nbsp;thầy&nbsp;bói&nbsp;vang&nbsp;lên,&nbsp;lặp&nbsp;đi&nbsp;lặp&nbsp;lại&nbsp;một&nbsp;cách&nbsp;đáng&nbsp;sợ:</span></p><p><em style=\"color: rgb(255, 255, 255);\">&quot;Cẩn&nbsp;thận&nbsp;người&nbsp;có&nbsp;vết&nbsp;sẹo...&nbsp;ở&nbsp;má&nbsp;trái.&quot;</em></p>','PUBLISHED',721,4,'2026-06-04 20:53:57','2026-06-04 20:53:46','2026-07-17 06:07:33',0,81,2,17,'chuong-1-vu-khuc-pha-quan'),(137,22,'CHƯƠNG 2: ĐÀO HOA CƯ TÝ',2,'<p><em style=\"color: rgb(255, 255, 255);\">&quot;Khi&nbsp;Đào&nbsp;Hoa&nbsp;cư&nbsp;tại&nbsp;cung&nbsp;Tý,&nbsp;nó&nbsp;chẳng&nbsp;lặng&nbsp;lẽ&nbsp;tỏa&nbsp;hương,&nbsp;mà&nbsp;bung&nbsp;nở&nbsp;giữa&nbsp;màn&nbsp;mưa,&nbsp;rực&nbsp;rỡ&nbsp;đến&nbsp;kiêu&nbsp;sa&nbsp;khiến&nbsp;kẻ&nbsp;bàng&nbsp;quan&nbsp;cũng&nbsp;phải&nbsp;ngước&nbsp;nhìn.&quot;</em></p><p><span style=\"color: rgb(255, 255, 255);\">Hai&nbsp;tuần&nbsp;đầu&nbsp;tiên&nbsp;ở&nbsp;GOLDEN&nbsp;trôi&nbsp;qua&nbsp;một&nbsp;cách&nbsp;bình&nbsp;lặng.&nbsp;Park&nbsp;Jimin&nbsp;đã&nbsp;chuẩn&nbsp;bị&nbsp;tinh&nbsp;thần&nbsp;bị&nbsp;vắt&nbsp;kiệt,&nbsp;bị&nbsp;bẻ&nbsp;gãy,&nbsp;bị&nbsp;nghiền&nbsp;nát&nbsp;như&nbsp;cách&nbsp;Jeon&nbsp;Jungkook&nbsp;đã&nbsp;làm&nbsp;với&nbsp;bản&nbsp;vẽ&nbsp;của&nbsp;cậu&nbsp;trong&nbsp;buổi&nbsp;phỏng&nbsp;vấn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Nhưng&nbsp;không&nbsp;có&nbsp;gì&nbsp;xảy&nbsp;ra&nbsp;cả.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jeon&nbsp;Jungkook&nbsp;xuất&nbsp;hiện&nbsp;trong&nbsp;văn&nbsp;phòng&nbsp;như&nbsp;một&nbsp;cơn&nbsp;gió.&nbsp;Đến,&nbsp;lướt&nbsp;qua,&nbsp;rồi&nbsp;biến&nbsp;mất.&nbsp;Những&nbsp;bước&nbsp;chân&nbsp;anh&nbsp;nhanh,&nbsp;gọn,&nbsp;không&nbsp;dư&nbsp;thừa&nbsp;một&nbsp;nhịp&nbsp;nào.&nbsp;Ánh&nbsp;mắt&nbsp;không&nbsp;dừng&nbsp;lại&nbsp;ở&nbsp;bất&nbsp;kỳ&nbsp;ai&nbsp;quá&nbsp;hai&nbsp;giây.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chính&nbsp;điều&nbsp;đó&nbsp;lại&nbsp;khiến&nbsp;Jimin&nbsp;thả&nbsp;lỏng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;được&nbsp;sắp&nbsp;xếp&nbsp;một&nbsp;chỗ&nbsp;ngồi&nbsp;gần&nbsp;cửa&nbsp;sổ,&nbsp;nơi&nbsp;ánh&nbsp;nắng&nbsp;buổi&nbsp;sáng&nbsp;được&nbsp;lọc&nbsp;qua&nbsp;lớp&nbsp;kính&nbsp;dày,&nbsp;phủ&nbsp;lên&nbsp;bàn&nbsp;làm&nbsp;việc&nbsp;một&nbsp;ánh&nbsp;sáng&nbsp;trong&nbsp;veo,&nbsp;đủ&nbsp;để&nbsp;khiến&nbsp;người&nbsp;ta&nbsp;có&nbsp;cảm&nbsp;giác&nbsp;thư&nbsp;thái&nbsp;đến&nbsp;lạ&nbsp;kì.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Công&nbsp;việc&nbsp;của&nbsp;cậu&nbsp;chủ&nbsp;yếu&nbsp;là&nbsp;những&nbsp;việc&nbsp;nhỏ&nbsp;như&nbsp;chỉnh&nbsp;sửa&nbsp;bản&nbsp;vẽ&nbsp;theo&nbsp;góp&nbsp;ý,&nbsp;sắp&nbsp;xếp&nbsp;hồ&nbsp;sơ,&nbsp;dựng&nbsp;lại&nbsp;file&nbsp;3D,&nbsp;hỗ&nbsp;trợ&nbsp;các&nbsp;anh&nbsp;chị&nbsp;trong&nbsp;nhóm.&nbsp;Những&nbsp;việc&nbsp;vặt&nbsp;không&nbsp;ai&nbsp;muốn&nbsp;làm&nbsp;nhưng&nbsp;buộc&nbsp;phải&nbsp;có&nbsp;người&nbsp;làm.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;cười&nbsp;nhiều,&nbsp;hài&nbsp;hước,&nbsp;lại&nbsp;rất&nbsp;tốt&nbsp;bụng&nbsp;và&nbsp;hào&nbsp;sảng&nbsp;nên&nbsp;luôn&nbsp;được&nbsp;mọi&nbsp;người&nbsp;yêu&nbsp;mến.&nbsp;Cậu&nbsp;sẵn&nbsp;sàng&nbsp;giúp&nbsp;đỡ,&nbsp;không&nbsp;ngại&nbsp;hỏi,&nbsp;cũng&nbsp;không&nbsp;ngại&nbsp;sai.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chỉ&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;ngắn,&nbsp;câu&nbsp;&quot;Jimin&nbsp;ơi&quot;&nbsp;đã&nbsp;trở&nbsp;thành&nbsp;một&nbsp;âm&nbsp;thanh&nbsp;quen&nbsp;thuộc&nbsp;trong&nbsp;văn&nbsp;phòng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Jimin&nbsp;ơi,&nbsp;giúp&nbsp;chị&nbsp;chỉnh&nbsp;lại&nbsp;layer&nbsp;bản&nbsp;này&nbsp;với?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Dạ&nbsp;được&nbsp;ạ!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Jimin&nbsp;ơi,&nbsp;em&nbsp;biết&nbsp;render&nbsp;Lumion&nbsp;không?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Dạ...&nbsp;em&nbsp;biết&nbsp;sơ&nbsp;sơ,&nbsp;để&nbsp;em&nbsp;thử!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Jimin&nbsp;ơi,&nbsp;đi&nbsp;ăn&nbsp;trưa&nbsp;không?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Dạ&nbsp;có&nbsp;chứ&nbsp;ạ!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Văn&nbsp;phòng&nbsp;vốn&nbsp;lạnh&nbsp;lẽo,&nbsp;nhưng&nbsp;góc&nbsp;nhỏ&nbsp;của&nbsp;Jimin&nbsp;lúc&nbsp;nào&nbsp;cũng&nbsp;sống&nbsp;động&nbsp;và&nbsp;đầy&nbsp;ắp&nbsp;tiếng&nbsp;cười.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cuộc&nbsp;sống&nbsp;của&nbsp;cậu&nbsp;cũng&nbsp;dần&nbsp;đi&nbsp;vào&nbsp;quỹ&nbsp;đạo.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Buổi&nbsp;sáng,&nbsp;Jimin&nbsp;vẫn&nbsp;hay&nbsp;chạy&nbsp;vội&nbsp;đến&nbsp;công&nbsp;ty&nbsp;với&nbsp;mái&nbsp;tóc&nbsp;còn&nbsp;hơi&nbsp;ẩm,&nbsp;áo&nbsp;sơ&nbsp;mi&nbsp;cài&nbsp;vội&nbsp;vàng&nbsp;đôi&nbsp;khi&nbsp;lệch&nbsp;một&nbsp;nút,&nbsp;hơi&nbsp;thở&nbsp;gấp&nbsp;gáp&nbsp;như&nbsp;thể&nbsp;chỉ&nbsp;cần&nbsp;chậm&nbsp;thêm&nbsp;một&nbsp;phút&nbsp;thôi&nbsp;là&nbsp;sẽ&nbsp;bị&nbsp;thế&nbsp;giới&nbsp;này&nbsp;bỏ&nbsp;lại&nbsp;phía&nbsp;sau.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Buổi&nbsp;chiều,&nbsp;cậu&nbsp;đi&nbsp;bộ&nbsp;ra&nbsp;trạm&nbsp;xe&nbsp;buýt.&nbsp;Và&nbsp;gần&nbsp;như&nbsp;ngày&nbsp;nào&nbsp;cũng&nbsp;vậy,&nbsp;Kim&nbsp;Taehyung&nbsp;đứng&nbsp;ở&nbsp;đó,&nbsp;dựa&nbsp;lưng&nbsp;vào&nbsp;cột,&nbsp;hai&nbsp;tay&nbsp;đút&nbsp;túi,&nbsp;ánh&nbsp;mắt&nbsp;lơ&nbsp;đãng&nbsp;như&nbsp;đang&nbsp;nghĩ&nbsp;về&nbsp;điều&nbsp;gì&nbsp;xa&nbsp;xôi.&nbsp;Nhưng&nbsp;chỉ&nbsp;cần&nbsp;nhìn&nbsp;thấy&nbsp;cậu,&nbsp;tất&nbsp;cả&nbsp;mệt&nbsp;mỏi&nbsp;đều&nbsp;tan&nbsp;biến,&nbsp;thay&nbsp;vào&nbsp;đó&nbsp;là&nbsp;một&nbsp;vẻ&nbsp;mặt&nbsp;ngốc&nbsp;nghếch&nbsp;quen&nbsp;thuộc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Họ&nbsp;chẳng&nbsp;nói&nbsp;những&nbsp;chuyện&nbsp;lớn&nbsp;lao.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Nay&nbsp;đi&nbsp;trễ&nbsp;nữa&nbsp;hả?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ừ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Mai&nbsp;trễ&nbsp;tiếp&nbsp;không?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Chắc&nbsp;là&nbsp;có.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;...&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chỉ&nbsp;là&nbsp;những&nbsp;câu&nbsp;nói&nbsp;vụn&nbsp;vặt,&nbsp;những&nbsp;câu&nbsp;chuyện&nbsp;chẳng&nbsp;đầu&nbsp;chẳng&nbsp;đuôi,&nbsp;những&nbsp;kế&nbsp;hoạch&nbsp;cuối&nbsp;tuần&nbsp;được&nbsp;vẽ&nbsp;ra&nbsp;rồi&nbsp;quên&nbsp;luôn.&nbsp;Nhưng&nbsp;kỳ&nbsp;lạ&nbsp;là,&nbsp;chính&nbsp;những&nbsp;thứ&nbsp;vô&nbsp;nghĩa&nbsp;ấy&nbsp;lại&nbsp;khiến&nbsp;thành&nbsp;phố&nbsp;này&nbsp;bớt&nbsp;đi&nbsp;một&nbsp;chút&nbsp;xa&nbsp;lạ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Mỗi&nbsp;chiều&nbsp;cuối&nbsp;tuần,&nbsp;đôi&nbsp;khi&nbsp;Taehyung&nbsp;vắng&nbsp;mặt,&nbsp;thay&nbsp;vào&nbsp;đó&nbsp;là&nbsp;Namjoon&nbsp;và&nbsp;Hoseok&nbsp;–&nbsp;những&nbsp;người&nbsp;bạn&nbsp;thuở&nbsp;nhỏ,&nbsp;gắn&nbsp;với&nbsp;Jimin&nbsp;từ&nbsp;những&nbsp;năm&nbsp;tháng&nbsp;còn&nbsp;chưa&nbsp;biết&nbsp;&quot;tương&nbsp;lai&quot;&nbsp;là&nbsp;thứ&nbsp;đáng&nbsp;sợ&nbsp;đến&nbsp;thế&nbsp;nào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Họ&nbsp;từng&nbsp;cùng&nbsp;nhau&nbsp;rời&nbsp;quê,&nbsp;mang&nbsp;theo&nbsp;balo,&nbsp;ước&nbsp;mơ&nbsp;và&nbsp;một&nbsp;niềm&nbsp;tin&nbsp;non&nbsp;trẻ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giờ&nbsp;đây,&nbsp;họ&nbsp;vẫn&nbsp;cười&nbsp;như&nbsp;vậy.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Vẫn&nbsp;chia&nbsp;nhau&nbsp;gói&nbsp;bánh,&nbsp;chai&nbsp;nước.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Vẫn&nbsp;đi&nbsp;bộ&nbsp;dưới&nbsp;tán&nbsp;cây&nbsp;như&nbsp;thể&nbsp;thế&nbsp;giới&nbsp;này&nbsp;chưa&nbsp;từng&nbsp;thay&nbsp;đổi.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Và&nbsp;rồi&nbsp;đêm&nbsp;xuống,&nbsp;Jimin&nbsp;lại&nbsp;trở&nbsp;về&nbsp;với&nbsp;thế&nbsp;giới&nbsp;của&nbsp;riêng&nbsp;mình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;thế&nbsp;giới&nbsp;khác&nbsp;ồn&nbsp;ào&nbsp;hơn,&nbsp;náo&nbsp;nhiệt&nbsp;hơn,&nbsp;nhưng&nbsp;cũng&nbsp;thân&nbsp;thuộc&nbsp;không&nbsp;kém.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;vẫn&nbsp;là&nbsp;Thống&nbsp;soái&nbsp;của&nbsp;BAN.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Tớ&nbsp;chi&nbsp;viện&nbsp;cho&nbsp;rồi,&nbsp;tấn&nbsp;công&nbsp;đi!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Yoongi&nbsp;hyung,&nbsp;đổi&nbsp;quân&nbsp;trang&nbsp;nào!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Kênh&nbsp;discord&nbsp;đầy&nbsp;ồn&nbsp;ào&nbsp;huyên&nbsp;náo,&nbsp;tiếng&nbsp;nói&nbsp;cười&nbsp;chồng&nbsp;lên&nbsp;nhau,&nbsp;rộn&nbsp;ràng&nbsp;như&nbsp;thể&nbsp;chưa&nbsp;từng&nbsp;có&nbsp;một&nbsp;ngày&nbsp;dài&nbsp;mệt&nbsp;mỏi&nbsp;nào&nbsp;tồn&nbsp;tại.</span></p><p><span style=\"color: rgb(255, 255, 255);\">_________________</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;buổi&nbsp;trưa&nbsp;hiếm&nbsp;hoi,&nbsp;khi&nbsp;công&nbsp;việc&nbsp;đã&nbsp;hoàn&nbsp;thành&nbsp;sớm&nbsp;hơn&nbsp;dự&nbsp;kiến&nbsp;và&nbsp;văn&nbsp;phòng&nbsp;rơi&nbsp;vào&nbsp;trạng&nbsp;thái&nbsp;yên&nbsp;tĩnh,&nbsp;Jimin&nbsp;ngồi&nbsp;xoay&nbsp;xoay&nbsp;cây&nbsp;bút&nbsp;chì&nbsp;trong&nbsp;tay,&nbsp;ánh&nbsp;mắt&nbsp;vô&nbsp;thức&nbsp;hướng&nbsp;ra&nbsp;phía&nbsp;dòng&nbsp;sông&nbsp;bên&nbsp;ngoài&nbsp;cửa&nbsp;kính.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Mặt&nbsp;nước&nbsp;phản&nbsp;chiếu&nbsp;ánh&nbsp;sáng&nbsp;thành&nbsp;những&nbsp;mảng&nbsp;lấp&nbsp;lánh,&nbsp;chậm&nbsp;rãi&nbsp;trôi&nbsp;đi&nbsp;như&nbsp;thể&nbsp;không&nbsp;có&nbsp;gì&nbsp;trên&nbsp;đời&nbsp;này&nbsp;đáng&nbsp;để&nbsp;vội&nbsp;vã.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;lật&nbsp;mặt&nbsp;sau&nbsp;của&nbsp;một&nbsp;tờ&nbsp;giấy&nbsp;tiến&nbsp;độ&nbsp;thi&nbsp;công,&nbsp;rồi&nbsp;bắt&nbsp;đầu&nbsp;vẽ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Không&nbsp;phải&nbsp;một&nbsp;công&nbsp;trình&nbsp;thiết&nbsp;kế&nbsp;chuẩn&nbsp;chỉnh,&nbsp;cũng&nbsp;chẳng&nbsp;phải&nbsp;thứ&nbsp;có&nbsp;thể&nbsp;đem&nbsp;đi&nbsp;trình&nbsp;bày&nbsp;trước&nbsp;khách&nbsp;hàng.&nbsp;Chỉ&nbsp;là&nbsp;một&nbsp;quán&nbsp;cà&nbsp;phê&nbsp;nhỏ&nbsp;nằm&nbsp;sát&nbsp;bên&nbsp;sông&nbsp;với&nbsp;mái&nbsp;hiên&nbsp;kéo&nbsp;dài&nbsp;không&nbsp;đều,&nbsp;bàn&nbsp;ghế&nbsp;đặt&nbsp;lệch,&nbsp;cây&nbsp;xanh&nbsp;mọc&nbsp;tự&nbsp;do&nbsp;không&nbsp;theo&nbsp;quy&nbsp;luật&nbsp;nào.&nbsp;Tất&nbsp;cả&nbsp;đều&nbsp;có&nbsp;chút&nbsp;gì&nbsp;đó&nbsp;sai&nbsp;lệch&nbsp;nhưng&nbsp;lại&nbsp;mang&nbsp;một&nbsp;thứ&nbsp;cảm&nbsp;giác&nbsp;rất&nbsp;sống&nbsp;động.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Khoảng&nbsp;này&nbsp;nếu&nbsp;làm&nbsp;thật,&nbsp;hệ&nbsp;mái&nbsp;sẽ&nbsp;không&nbsp;đủ&nbsp;độ&nbsp;cứng.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giọng&nbsp;nói&nbsp;vang&nbsp;lên&nbsp;ngay&nbsp;phía&nbsp;sau,&nbsp;gần&nbsp;đến&nbsp;mức&nbsp;khiến&nbsp;Jimin&nbsp;giật&nbsp;mình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;quay&nbsp;lại,&nbsp;bắt&nbsp;gặp&nbsp;Jeon&nbsp;Jungkook&nbsp;đang&nbsp;đứng&nbsp;đó&nbsp;từ&nbsp;lúc&nbsp;nào.&nbsp;Không&nbsp;một&nbsp;tiếng&nbsp;động,&nbsp;giống&nbsp;như&nbsp;anh&nbsp;vốn&nbsp;dĩ&nbsp;đã&nbsp;ở&nbsp;trong&nbsp;không&nbsp;gian&nbsp;này&nbsp;từ&nbsp;trước&nbsp;khi&nbsp;cậu&nbsp;nhận&nbsp;ra.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Khoảng&nbsp;cách&nbsp;giữa&nbsp;họ&nbsp;gần&nbsp;hơn&nbsp;bình&nbsp;thường,&nbsp;đến&nbsp;mức&nbsp;Jimin&nbsp;có&nbsp;thể&nbsp;ngửi&nbsp;thấy&nbsp;mùi&nbsp;gỗ&nbsp;đàn&nbsp;hương&nbsp;thoang&nbsp;thoảng&nbsp;quen&nbsp;thuộc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Em&nbsp;chỉ&nbsp;vẽ&nbsp;linh&nbsp;tinh&nbsp;thôi.&quot;&nbsp;cậu&nbsp;vội&nbsp;giấu&nbsp;bản&nbsp;vẽ.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Tôi&nbsp;biết.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;kéo&nbsp;lại&nbsp;tờ&nbsp;giấy,&nbsp;rất&nbsp;tự&nbsp;nhiên&nbsp;mà&nbsp;rút&nbsp;cây&nbsp;bút&nbsp;chì&nbsp;khỏi&nbsp;tay&nbsp;Jimin.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;cúi&nbsp;xuống&nbsp;chỉnh&nbsp;sửa&nbsp;vài&nbsp;nét.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Những&nbsp;đường&nbsp;vẽ&nbsp;của&nbsp;anh&nbsp;dứt&nbsp;khoát,&nbsp;chính&nbsp;xác,&nbsp;nhưng&nbsp;không&nbsp;hề&nbsp;phá&nbsp;đi&nbsp;cái&nbsp;hồn&nbsp;ban&nbsp;đầu&nbsp;của&nbsp;bản&nbsp;vẽ,&nbsp;ngược&nbsp;lại&nbsp;còn&nbsp;khiến&nbsp;nó&nbsp;trở&nbsp;nên&nbsp;khả&nbsp;thi&nbsp;hơn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Nếu&nbsp;muốn&nbsp;giữ&nbsp;không&nbsp;gian&nbsp;mở&nbsp;như&nbsp;thế&nbsp;này,&nbsp;em&nbsp;có&nbsp;thể&nbsp;dùng&nbsp;dầm&nbsp;thép&nbsp;chữ&nbsp;I&nbsp;hoặc&nbsp;hệ&nbsp;giàn&nbsp;nhẹ,&quot;&nbsp;anh&nbsp;nói&nbsp;chậm&nbsp;rãi.&nbsp;&quot;Nhẹ&nbsp;hơn&nbsp;bê&nbsp;tông,&nbsp;nhưng&nbsp;vượt&nbsp;nhịp&nbsp;tốt&nbsp;hơn.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cột&nbsp;đặt&nbsp;lệch&nbsp;thì&nbsp;được.&nbsp;Nhưng&nbsp;phải&nbsp;có&nbsp;hệ&nbsp;chịu&nbsp;lực&nbsp;rõ&nbsp;ràng.&quot;Anh&nbsp;dừng&nbsp;lại&nbsp;một&nbsp;nhịp,&nbsp;ánh&nbsp;mắt&nbsp;chậm&nbsp;rãi&nbsp;chuyển&nbsp;sang&nbsp;Jimin.&nbsp;&quot;Và&nbsp;đừng&nbsp;để&nbsp;nó&nbsp;tồn&nbsp;tại&nbsp;chỉ&nbsp;vì&nbsp;trông&nbsp;đẹp.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;im&nbsp;lặng&nbsp;lắng&nbsp;nghe,&nbsp;ánh&nbsp;mắt&nbsp;dõi&nbsp;theo&nbsp;từng&nbsp;chuyển&nbsp;động&nbsp;của&nbsp;đầu&nbsp;bút.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Còn&nbsp;cái&nbsp;này?&quot;&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;dừng&nbsp;lại&nbsp;ở&nbsp;một&nbsp;khoảng&nbsp;trống&nbsp;chưa&nbsp;hoàn&nbsp;thiện,&nbsp;một&nbsp;vùng&nbsp;trắng&nbsp;nằm&nbsp;ngay&nbsp;giữa&nbsp;bản&nbsp;vẽ,&nbsp;nơi&nbsp;đáng&nbsp;lẽ&nbsp;phải&nbsp;là&nbsp;điểm&nbsp;nhấn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ánh&nbsp;mắt&nbsp;anh&nbsp;lần&nbsp;nữa&nbsp;nâng&nbsp;lên,&nbsp;nhìn&nbsp;thẳng&nbsp;vào&nbsp;Jimin.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;khẽ&nbsp;khựng&nbsp;lại.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Rồi&nbsp;như&nbsp;thể&nbsp;vừa&nbsp;nắm&nbsp;được&nbsp;một&nbsp;ý&nbsp;nghĩ&nbsp;còn&nbsp;chưa&nbsp;kịp&nbsp;thành&nbsp;hình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Em&nbsp;không&nbsp;muốn&nbsp;đặt&nbsp;thêm&nbsp;gì&nbsp;ở&nbsp;đây.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ngón&nbsp;tay&nbsp;cậu&nbsp;chạm&nbsp;xuống&nbsp;giấy.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Em&nbsp;muốn&nbsp;để&nbsp;trống.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;nhướng&nbsp;mày.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Nhưng&nbsp;không&nbsp;phải&nbsp;là&nbsp;khoảng&nbsp;trống&nbsp;vô&nbsp;nghĩa,&quot;&nbsp;Jimin&nbsp;tiếp&nbsp;tục,&nbsp;giọng&nbsp;chậm&nbsp;lại&nbsp;khi&nbsp;ý&nbsp;tưởng&nbsp;dần&nbsp;rõ&nbsp;ràng&nbsp;hơn.&nbsp;&quot;Em&nbsp;muốn&nbsp;phần&nbsp;này&nbsp;là&nbsp;một&nbsp;khoảng&nbsp;sân&nbsp;chìm,&nbsp;thấp&nbsp;hơn&nbsp;mặt&nbsp;sàn&nbsp;chính&nbsp;một&nbsp;chút.&nbsp;Không&nbsp;mái&nbsp;che.&nbsp;Không&nbsp;bàn&nbsp;ghế&nbsp;cố&nbsp;định.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Chỉ&nbsp;có&nbsp;nước.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;nhìn&nbsp;Jungkook,&nbsp;như&nbsp;chờ&nbsp;một&nbsp;phản&nbsp;ứng&nbsp;nào&nbsp;đó.&nbsp;Nhưng&nbsp;gương&nbsp;mặt&nbsp;anh&nbsp;vẫn&nbsp;bình&nbsp;thản&nbsp;đến&nbsp;mức&nbsp;không&nbsp;thể&nbsp;đọc&nbsp;được.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Một&nbsp;mặt&nbsp;hồ&nbsp;nông,&nbsp;mở&nbsp;ra&nbsp;một&nbsp;trục&nbsp;nhìn&nbsp;thẳng&nbsp;ra&nbsp;phía&nbsp;dòng&nbsp;sông.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ban&nbsp;ngày,&nbsp;nó&nbsp;phản&nbsp;chiếu&nbsp;bầu&nbsp;trời.&nbsp;Ban&nbsp;đêm,&nbsp;ánh&nbsp;đèn&nbsp;sẽ&nbsp;giữ&nbsp;lại&nbsp;cảm&nbsp;giác&nbsp;đó.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;dùng&nbsp;đầu&nbsp;bút&nbsp;khẽ&nbsp;chạm&nbsp;xuống&nbsp;mặt&nbsp;giấy&nbsp;một&nbsp;nhịp,&nbsp;rồi&nbsp;đặt&nbsp;lại&nbsp;cây&nbsp;bút&nbsp;vào&nbsp;tay&nbsp;Jimin.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Vậy&nbsp;thì&nbsp;em&nbsp;hãy&nbsp;tự&nbsp;tay&nbsp;hoàn&nbsp;thiện&nbsp;nó&nbsp;đi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giọng&nbsp;anh&nbsp;trầm&nbsp;xuống,&nbsp;không&nbsp;nhanh&nbsp;không&nbsp;chậm.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Không&nbsp;phải&nbsp;thứ&nbsp;gì&nbsp;cũng&nbsp;cần&nbsp;lý&nbsp;do.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Nhưng&nbsp;để&nbsp;giữ&nbsp;được&nbsp;thứ&nbsp;không&nbsp;cần&nbsp;lý&nbsp;do,&nbsp;em&nbsp;phải&nbsp;kiểm&nbsp;soát&nbsp;được&nbsp;tất&nbsp;cả&nbsp;những&nbsp;thứ&nbsp;còn&nbsp;lại.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Câu&nbsp;nói&nbsp;khiến&nbsp;tâm&nbsp;trí&nbsp;của&nbsp;Jimin&nbsp;đứng&nbsp;yên&nbsp;tại&nbsp;chỗ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Còn&nbsp;Jungkook&nbsp;cứ&nbsp;thế&nbsp;bước&nbsp;đi.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Đi&nbsp;được&nbsp;vài&nbsp;bước,&nbsp;anh&nbsp;đột&nbsp;ngột&nbsp;dừng&nbsp;lại,&nbsp;nghiêng&nbsp;đầu&nbsp;nói&nbsp;thêm&nbsp;một&nbsp;câu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Hơn&nbsp;nữa,&nbsp;hãy&nbsp;luôn&nbsp;mang&nbsp;sổ&nbsp;sketch&nbsp;bên&nbsp;mình.&nbsp;Đừng&nbsp;thiết&nbsp;kế&nbsp;lên&nbsp;trên&nbsp;giấy&nbsp;tờ&nbsp;thi&nbsp;công.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">____________________</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;ngồi&nbsp;trong&nbsp;văn&nbsp;phòng&nbsp;riêng&nbsp;của&nbsp;mình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;luôn&nbsp;ưa&nbsp;sự&nbsp;đơn&nbsp;sắc&nbsp;và&nbsp;gọn&nbsp;gàng,&nbsp;nên&nbsp;mọi&nbsp;thứ&nbsp;xung&nbsp;quanh&nbsp;cũng&nbsp;được&nbsp;sắp&nbsp;xếp&nbsp;đúng&nbsp;như&nbsp;vậy.&nbsp;Ngăn&nbsp;nắp,&nbsp;tối&nbsp;giản,&nbsp;gần&nbsp;như&nbsp;không&nbsp;có&nbsp;chỗ&nbsp;cho&nbsp;bất&nbsp;kỳ&nbsp;sự&nbsp;dư&nbsp;thừa&nbsp;nào.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bức&nbsp;tường&nbsp;kính&nbsp;một&nbsp;chiều&nbsp;mở&nbsp;ra&nbsp;không&nbsp;gian&nbsp;bên&nbsp;ngoài,&nbsp;cho&nbsp;phép&nbsp;anh&nbsp;quan&nbsp;sát&nbsp;mọi&nbsp;thứ&nbsp;xung&nbsp;quanh.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;đặc&nbsp;quyền&nbsp;của&nbsp;kẻ&nbsp;bề&nbsp;trên.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ánh&nbsp;mắt&nbsp;anh&nbsp;dừng&nbsp;lại&nbsp;nơi&nbsp;một&nbsp;bóng&nbsp;dáng&nbsp;quen&nbsp;thuộc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;vừa&nbsp;đứng&nbsp;dậy,&nbsp;cầm&nbsp;theo&nbsp;bình&nbsp;nước&nbsp;của&nbsp;mình,&nbsp;bước&nbsp;ra&nbsp;ngoài.&nbsp;Khi&nbsp;đi&nbsp;ngang&nbsp;qua&nbsp;bàn&nbsp;của&nbsp;một&nbsp;cô&nbsp;đồng&nbsp;nghiệp,&nbsp;cậu&nbsp;tiện&nbsp;tay&nbsp;cầm&nbsp;thêm&nbsp;một&nbsp;bình&nbsp;khác,&nbsp;động&nbsp;tác&nbsp;tự&nbsp;nhiên&nbsp;đến&nbsp;mức&nbsp;giống&nbsp;như&nbsp;đã&nbsp;lặp&nbsp;lại&nbsp;quá&nbsp;nhiều&nbsp;lần.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;nhìn&nbsp;theo&nbsp;từng&nbsp;bước&nbsp;chân&nbsp;của&nbsp;cậu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;vốn&nbsp;là&nbsp;người&nbsp;cực&nbsp;kỳ&nbsp;tập&nbsp;trung.&nbsp;Mọi&nbsp;thứ&nbsp;anh&nbsp;làm&nbsp;đều&nbsp;có&nbsp;mục&nbsp;đích,&nbsp;mọi&nbsp;hành&nbsp;động&nbsp;đều&nbsp;có&nbsp;lý&nbsp;do&nbsp;rõ&nbsp;ràng.&nbsp;Anh&nbsp;không&nbsp;có&nbsp;thói&nbsp;quen&nbsp;để&nbsp;tâm&nbsp;đến&nbsp;những&nbsp;chuyện&nbsp;ngoài&nbsp;lề.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Không&nbsp;hiểu&nbsp;vì&nbsp;sao&nbsp;bộ&nbsp;não&nbsp;anh&nbsp;gần&nbsp;lại&nbsp;tự&nbsp;động&nbsp;ghi&nbsp;nhớ&nbsp;những&nbsp;thứ&nbsp;rất&nbsp;kì&nbsp;lạ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;biết,&nbsp;mỗi&nbsp;lần&nbsp;Jimin&nbsp;bước&nbsp;vào&nbsp;văn&nbsp;phòng&nbsp;sẽ&nbsp;khẽ&nbsp;rùng&nbsp;mình&nbsp;một&nbsp;cái&nbsp;rất&nbsp;nhẹ,&nbsp;vì&nbsp;điều&nbsp;hòa&nbsp;được&nbsp;lắp&nbsp;ngay&nbsp;gần&nbsp;cửa.&nbsp;Và&nbsp;chỉ&nbsp;vài&nbsp;bước&nbsp;sau&nbsp;đó,&nbsp;khi&nbsp;trở&nbsp;về&nbsp;chỗ&nbsp;ngồi&nbsp;cạnh&nbsp;cửa&nbsp;sổ,&nbsp;cảm&nbsp;giác&nbsp;lạnh&nbsp;sẽ&nbsp;biến&nbsp;mất&nbsp;vì&nbsp;nơi&nbsp;đó&nbsp;luôn&nbsp;đón&nbsp;nắng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;biết&nbsp;Jimin&nbsp;có&nbsp;thể&nbsp;dễ&nbsp;dàng&nbsp;bắt&nbsp;chuyện&nbsp;với&nbsp;bất&nbsp;kỳ&nbsp;ai&nbsp;một&nbsp;cách&nbsp;tự&nbsp;nhiên&nbsp;và&nbsp;thân&nbsp;thiết,&nbsp;như&nbsp;thể&nbsp;khoảng&nbsp;cách&nbsp;giữa&nbsp;người&nbsp;với&nbsp;người&nbsp;không&nbsp;hề&nbsp;tồn&nbsp;tại&nbsp;trong&nbsp;thế&nbsp;giới&nbsp;của&nbsp;cậu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;biết&nbsp;Jimin&nbsp;thường&nbsp;đến&nbsp;sớm&nbsp;hơn&nbsp;giờ&nbsp;làm&nbsp;đúng&nbsp;ba&nbsp;phút&nbsp;vào&nbsp;những&nbsp;ngày&nbsp;trời&nbsp;đẹp,&nbsp;và&nbsp;muộn&nbsp;hơn&nbsp;đúng&nbsp;bảy&nbsp;phút&nbsp;vào&nbsp;những&nbsp;ngày&nbsp;trời&nbsp;mưa.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;biết&nbsp;Jimin&nbsp;thường&nbsp;mặc&nbsp;những&nbsp;gam&nbsp;màu&nbsp;nổi&nbsp;bật&nbsp;khác&nbsp;hẳn&nbsp;với&nbsp;sự&nbsp;đơn&nbsp;sắc&nbsp;trong&nbsp;thế&nbsp;giới&nbsp;của&nbsp;anh.&nbsp;Và&nbsp;trong&nbsp;tất&nbsp;cả&nbsp;những&nbsp;bộ&nbsp;trang&nbsp;phục&nbsp;ấy,&nbsp;luôn&nbsp;có&nbsp;một&nbsp;thứ&nbsp;không&nbsp;bao&nbsp;giờ&nbsp;thay&nbsp;đổi:&nbsp;sợi&nbsp;dây&nbsp;chuyền&nbsp;dây&nbsp;đen,&nbsp;cùng&nbsp;chiếc&nbsp;lắc&nbsp;tay&nbsp;có&nbsp;họa&nbsp;tiết&nbsp;tương&nbsp;tự.&nbsp;Một&nbsp;hình&nbsp;thù&nbsp;lạ&nbsp;lẫm&nbsp;mà&nbsp;Jungkook&nbsp;chưa&nbsp;từng&nbsp;thấy&nbsp;qua.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;cũng&nbsp;rất&nbsp;thích&nbsp;mái&nbsp;tóc&nbsp;cậu.&nbsp;Bồng&nbsp;bềnh,&nbsp;hơi&nbsp;rối&nbsp;có&nbsp;chủ&nbsp;ý,&nbsp;vài&nbsp;lọn&nbsp;tóc&nbsp;rơi&nbsp;xuống&nbsp;trán.&nbsp;Màu&nbsp;nâu&nbsp;trà&nbsp;dưới&nbsp;ánh&nbsp;nắng&nbsp;sẽ&nbsp;trở&nbsp;nên&nbsp;lấp&nbsp;lánh,&nbsp;như&nbsp;thể&nbsp;có&nbsp;thứ&nbsp;gì&nbsp;đó&nbsp;đang&nbsp;chuyển&nbsp;động&nbsp;rất&nbsp;khẽ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Anh&nbsp;còn&nbsp;chú&nbsp;ý&nbsp;với&nbsp;việc&nbsp;mỗi&nbsp;cuối&nbsp;tuần&nbsp;cậu&nbsp;sẽ&nbsp;ăn&nbsp;diện&nbsp;hơn&nbsp;một&nbsp;chút&nbsp;và&nbsp;sẽ&nbsp;tụ&nbsp;tập&nbsp;cùng&nbsp;bạn&nbsp;bè.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Những&nbsp;điều&nbsp;nhỏ&nbsp;nhặt,&nbsp;không&nbsp;cần&nbsp;thiết,&nbsp;không&nbsp;hề&nbsp;liên&nbsp;quan&nbsp;đến&nbsp;cuộc&nbsp;sống&nbsp;của&nbsp;anh.&nbsp;Vậy&nbsp;mà&nbsp;vẫn&nbsp;lặng&nbsp;lẽ&nbsp;khắc&nbsp;sâu&nbsp;vào&nbsp;lòng&nbsp;anh,&nbsp;rõ&nbsp;ràng&nbsp;đến&nbsp;mức&nbsp;anh&nbsp;không&nbsp;thể&nbsp;phủ&nbsp;nhận.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;thật&nbsp;sự&nbsp;không&nbsp;hiểu&nbsp;bản&nbsp;thân&nbsp;mình&nbsp;đang&nbsp;bị&nbsp;làm&nbsp;sao.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Khi&nbsp;tan&nbsp;làm,&nbsp;Jimin&nbsp;luôn&nbsp;đi&nbsp;về&nbsp;phía&nbsp;trạm&nbsp;xe&nbsp;buýt.&nbsp;Ở&nbsp;đó,&nbsp;gần&nbsp;như&nbsp;ngày&nbsp;nào&nbsp;cũng&nbsp;người&nbsp;đứng&nbsp;đợi,&nbsp;dáng&nbsp;vẻ&nbsp;của&nbsp;họ&nbsp;đầy&nbsp;sức&nbsp;sống&nbsp;tuổi&nbsp;trẻ,&nbsp;nhưng&nbsp;nụ&nbsp;cười&nbsp;thì&nbsp;lại&nbsp;có&nbsp;phần&nbsp;ngốc&nbsp;nghếch.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;đã&nbsp;nhìn&nbsp;thấy&nbsp;cảnh&nbsp;đó&nbsp;nhiều&nbsp;lần,&nbsp;đủ&nbsp;để&nbsp;nhận&nbsp;ra,&nbsp;cuộc&nbsp;sống&nbsp;của&nbsp;Jimin&nbsp;luôn&nbsp;có&nbsp;người&nbsp;đồng&nbsp;hành.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;rực&nbsp;rỡ,&nbsp;phóng&nbsp;khoáng,&nbsp;tùy&nbsp;hứng.&nbsp;Hoàn&nbsp;toàn&nbsp;khác&nbsp;với&nbsp;thế&nbsp;giới&nbsp;của&nbsp;anh,&nbsp;nơi&nbsp;mọi&nbsp;thứ&nbsp;đều&nbsp;được&nbsp;sắp&nbsp;xếp&nbsp;cẩn&nbsp;thận,&nbsp;chính&nbsp;xác&nbsp;đến&nbsp;từng&nbsp;chi&nbsp;tiết.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Hai&nbsp;đường&nbsp;thẳng&nbsp;không&nbsp;nên&nbsp;có&nbsp;điểm&nbsp;giao.&nbsp;Vậy&nbsp;mà&nbsp;ánh&nbsp;mắt&nbsp;anh&nbsp;vẫn&nbsp;dừng&nbsp;lại&nbsp;hết&nbsp;lần&nbsp;này&nbsp;đến&nbsp;lần&nbsp;khác.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;rời&nbsp;mắt&nbsp;đi,&nbsp;nhưng&nbsp;chỉ&nbsp;vài&nbsp;giây&nbsp;sau&nbsp;lại&nbsp;vô&nbsp;thức&nbsp;nhìn&nbsp;lại.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giống&nbsp;như&nbsp;cơ&nbsp;thể&nbsp;đã&nbsp;quen&nbsp;với&nbsp;một&nbsp;quỹ&nbsp;đạo&nbsp;mới&nbsp;một&nbsp;quỹ&nbsp;đạo&nbsp;mà&nbsp;chính&nbsp;anh&nbsp;cũng&nbsp;chưa&nbsp;kịp&nbsp;nắm&nbsp;bắt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Và&nbsp;điều&nbsp;khiến&nbsp;anh&nbsp;bối&nbsp;rối&nbsp;nhất&nbsp;không&nbsp;phải&nbsp;việc&nbsp;bản&nbsp;thân&nbsp;anh&nbsp;đang&nbsp;nhìn.&nbsp;Mà&nbsp;anh&nbsp;không&nbsp;biết&nbsp;tại&nbsp;sao&nbsp;mình&nbsp;lại&nbsp;không&nbsp;thể&nbsp;dừng&nbsp;lại.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chiều&nbsp;hôm&nbsp;đó,&nbsp;mưa&nbsp;đến&nbsp;bất&nbsp;chợt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đứng&nbsp;dưới&nbsp;mái&nbsp;che&nbsp;của&nbsp;trạm&nbsp;xe&nbsp;buýt,&nbsp;nhìn&nbsp;những&nbsp;giọt&nbsp;nước&nbsp;đập&nbsp;xuống&nbsp;mặt&nbsp;đường,&nbsp;bắn&nbsp;lên&nbsp;thành&nbsp;những&nbsp;hạt&nbsp;nhỏ&nbsp;li&nbsp;ti.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;đã&nbsp;nhắn&nbsp;trước&nbsp;là&nbsp;sẽ&nbsp;tăng&nbsp;ca,&nbsp;nên&nbsp;cậu&nbsp;chỉ&nbsp;có&nbsp;thể&nbsp;đứng&nbsp;một&nbsp;mình&nbsp;chờ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;chiếc&nbsp;xe&nbsp;đen&nbsp;dừng&nbsp;lại&nbsp;trước&nbsp;mặt.&nbsp;Cửa&nbsp;kính&nbsp;hạ&nbsp;xuống&nbsp;một&nbsp;nửa,&nbsp;gương&nbsp;mặt&nbsp;Jungkook&nbsp;xuất&nbsp;hiện&nbsp;phía&nbsp;sau&nbsp;lớp&nbsp;kính.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Em&nbsp;học&nbsp;Đại&nbsp;học&nbsp;Kiến&nbsp;Trúc&nbsp;đúng&nbsp;chứ?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;hơi&nbsp;bối&nbsp;rối&nbsp;vì&nbsp;không&nbsp;hiểu&nbsp;chuyện&nbsp;gì&nbsp;đang&nbsp;diễn&nbsp;ra,&nbsp;nhưng&nbsp;vẫn&nbsp;gật&nbsp;đầu.&nbsp;Jungkook&nbsp;hất&nbsp;nhẹ&nbsp;cằm&nbsp;về&nbsp;phía&nbsp;ghế&nbsp;phụ,&nbsp;giọng&nbsp;điềm&nbsp;nhiên&nbsp;như&nbsp;một&nbsp;mệnh&nbsp;lệnh.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Lên&nbsp;xe&nbsp;đi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Tôi&nbsp;có&nbsp;việc&nbsp;cần&nbsp;đến&nbsp;khu&nbsp;gần&nbsp;đó.&quot;&nbsp;Jungkook&nbsp;nói,&nbsp;giọng&nbsp;đều&nbsp;đều.&nbsp;&quot;Em&nbsp;chỉ&nbsp;đường&nbsp;nhé.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;khẽ&nbsp;à&nbsp;một&nbsp;tiếng,&nbsp;rồi&nbsp;cậu&nbsp;mở&nbsp;cửa&nbsp;ngồi&nbsp;vào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Không&nbsp;gian&nbsp;trong&nbsp;xe&nbsp;ấm&nbsp;hơn,&nbsp;mùi&nbsp;gỗ&nbsp;đàn&nbsp;hương&nbsp;quen&nbsp;thuộc&nbsp;thoang&nbsp;thoảng&nbsp;trong&nbsp;không&nbsp;khí.&nbsp;Mưa&nbsp;gõ&nbsp;lên&nbsp;cửa&nbsp;kính&nbsp;thành&nbsp;những&nbsp;nhịp&nbsp;đều&nbsp;đều,&nbsp;hòa&nbsp;cùng&nbsp;bản&nbsp;nhạc&nbsp;đang&nbsp;phát.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Qua&nbsp;vài&nbsp;bản&nbsp;nhạc&nbsp;buồn,&nbsp;</span><em style=\"color: rgb(255, 255, 255);\">Still&nbsp;with&nbsp;you</em><span style=\"color: rgb(255, 255, 255);\">&nbsp;vang&nbsp;lên.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Em&nbsp;rất&nbsp;thích&nbsp;bài&nbsp;này.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Tôi&nbsp;rất&nbsp;thích&nbsp;bài&nbsp;này.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cả&nbsp;hai&nbsp;cùng&nbsp;nói,&nbsp;gần&nbsp;như&nbsp;cùng&nbsp;lúc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;quay&nbsp;sang&nbsp;nhìn&nbsp;anh,&nbsp;có&nbsp;chút&nbsp;bất&nbsp;ngờ.&nbsp;Trong&nbsp;tưởng&nbsp;tượng&nbsp;của&nbsp;cậu,&nbsp;người&nbsp;như&nbsp;Jungkook&nbsp;hẳn&nbsp;sẽ&nbsp;nghe&nbsp;nhạc&nbsp;cổ&nbsp;điển,&nbsp;ngồi&nbsp;một&nbsp;mình&nbsp;trong&nbsp;không&nbsp;gian&nbsp;sang&nbsp;trọng&nbsp;cùng&nbsp;ly&nbsp;rượu&nbsp;vang&nbsp;và&nbsp;chiếc&nbsp;đĩa&nbsp;than&nbsp;đắt&nbsp;tiền.&nbsp;Giọng&nbsp;câu&nbsp;nhẹ&nbsp;nhàng&nbsp;cảm&nbsp;thán.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Trùng&nbsp;hợp&nbsp;thật.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;không&nbsp;đáp&nbsp;ngay.&nbsp;Đợi&nbsp;đoạn&nbsp;intro&nbsp;trôi&nbsp;qua,&nbsp;anh&nbsp;mới&nbsp;vu&nbsp;vơ&nbsp;nói&nbsp;một&nbsp;câu.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Rất&nbsp;hợp&nbsp;để&nbsp;nghe&nbsp;khi&nbsp;trời&nbsp;mưa.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cả&nbsp;hai&nbsp;lại&nbsp;im&nbsp;lặng&nbsp;nhưng&nbsp;không&nbsp;hề&nbsp;gượng&nbsp;gạo.&nbsp;Tiếng&nbsp;mưa&nbsp;và&nbsp;âm&nbsp;nhạc&nbsp;đủ&nbsp;để&nbsp;lấp&nbsp;đầy&nbsp;khoảng&nbsp;trống&nbsp;giữa&nbsp;họ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Một&nbsp;lúc&nbsp;sau,&nbsp;Jungkook&nbsp;lên&nbsp;tiếng,&nbsp;mắt&nbsp;vẫn&nbsp;nhìn&nbsp;đường.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Người&nbsp;hay&nbsp;về&nbsp;cùng&nbsp;em&nbsp;đâu?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;mất&nbsp;vài&nbsp;giây&nbsp;để&nbsp;tiếp&nbsp;thu&nbsp;câu&nbsp;hỏi.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;À,&nbsp;là&nbsp;Kim&nbsp;Taehyung.&nbsp;Hôm&nbsp;nay&nbsp;cậu&nbsp;ấy&nbsp;phải&nbsp;tăng&nbsp;ca.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Bạn&nbsp;trai&nbsp;sao?&quot;&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Là&nbsp;bạn&nbsp;thân.&nbsp;Chúng&nbsp;em&nbsp;ở&nbsp;cùng&nbsp;phòng&nbsp;ký&nbsp;túc&nbsp;xá.&nbsp;Cậu&nbsp;ấy&nbsp;cũng&nbsp;làm&nbsp;việc&nbsp;ở&nbsp;gần&nbsp;đây.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jungkook&nbsp;chỉ&nbsp;ồ&nbsp;một&nbsp;tiếng,&nbsp;vẫn&nbsp;tập&nbsp;trung&nbsp;lái&nbsp;xe.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cuộc&nbsp;trò&nbsp;chuyện&nbsp;sau&nbsp;đó&nbsp;diễn&nbsp;ra&nbsp;rất&nbsp;tự&nbsp;nhiên.&nbsp;Jimin&nbsp;là&nbsp;người&nbsp;rất&nbsp;hoạt&nbsp;ngôn,&nbsp;cậu&nbsp;có&nbsp;thể&nbsp;vu&nbsp;vơ&nbsp;nói&nbsp;đủ&nbsp;thứ&nbsp;chuyện&nbsp;trên&nbsp;đời,&nbsp;hay&nbsp;đặt&nbsp;câu&nbsp;hỏi&nbsp;và&nbsp;tò&nbsp;mò&nbsp;về&nbsp;mọi&nbsp;thứ.&nbsp;Jungkook&nbsp;không&nbsp;phải&nbsp;kiểu&nbsp;người&nbsp;nói&nbsp;nhiều,&nbsp;nhưng&nbsp;anh&nbsp;luôn&nbsp;có&nbsp;câu&nbsp;trả&nbsp;lời.&nbsp;Từ&nbsp;âm&nbsp;nhạc,&nbsp;nghệ&nbsp;thuật&nbsp;cho&nbsp;đến&nbsp;kiến&nbsp;trúc,&nbsp;không&nbsp;có&nbsp;câu&nbsp;hỏi&nbsp;nào&nbsp;bị&nbsp;bỏ&nbsp;lửng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Giữa&nbsp;cơn&nbsp;mưa&nbsp;bất&nbsp;chợt&nbsp;của&nbsp;một&nbsp;buổi&nbsp;chiều&nbsp;bình&nbsp;thường,&nbsp;không&nbsp;hề&nbsp;có&nbsp;lấy&nbsp;một&nbsp;khoảnh&nbsp;khắc&nbsp;nào&nbsp;khiến&nbsp;họ&nbsp;cảm&nbsp;thấy&nbsp;xa&nbsp;lạ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">_________________________</span></p><p><span style=\"color: rgb(255, 255, 255);\">Buổi&nbsp;tối&nbsp;tại&nbsp;ký&nbsp;túc&nbsp;xá,&nbsp;cửa&nbsp;phòng&nbsp;bật&nbsp;mở&nbsp;cái&nbsp;&quot;rầm&quot;,&nbsp;Taehyung&nbsp;bước&nbsp;vào&nbsp;trong&nbsp;tình&nbsp;trạng&nbsp;ướt&nbsp;mưa&nbsp;từ&nbsp;đầu&nbsp;đến&nbsp;chân,&nbsp;tóc&nbsp;nhỏ&nbsp;nước&nbsp;xuống&nbsp;sàn,&nbsp;mặt&nbsp;mũi&nbsp;mệt&nbsp;rã&nbsp;rời,&nbsp;chưa&nbsp;kịp&nbsp;nói&nbsp;câu&nbsp;nào&nbsp;đã&nbsp;quăng&nbsp;balo&nbsp;sang&nbsp;một&nbsp;bên&nbsp;rồi&nbsp;ngã&nbsp;thẳng&nbsp;lên&nbsp;giường&nbsp;của&nbsp;Jimin&nbsp;như&nbsp;một&nbsp;cái&nbsp;xác&nbsp;không&nbsp;hồn.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đang&nbsp;chăm&nbsp;chú&nbsp;nhìn&nbsp;màn&nbsp;hình,&nbsp;quay&nbsp;sang&nbsp;thấy&nbsp;cả&nbsp;người&nbsp;ướt&nbsp;nhẹp&nbsp;của&nbsp;cậu&nbsp;ta&nbsp;nằm&nbsp;chễm&nbsp;chệ&nbsp;trên&nbsp;giường&nbsp;mình,&nbsp;Jimin&nbsp;hét&nbsp;lên&nbsp;một&nbsp;tiếng.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Này&nbsp;Kim&nbsp;Taehyung!!!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ôi&nbsp;mệt&nbsp;chết&nbsp;tớ&nbsp;rồi.&nbsp;Cho&nbsp;tớ&nbsp;nằm&nbsp;một&nbsp;tí&nbsp;thôi.&quot;&nbsp;Taehyung&nbsp;lẩm&nbsp;bẩm,&nbsp;giọng&nbsp;kéo&nbsp;dài&nbsp;như&nbsp;sắp&nbsp;tắt&nbsp;thở.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đi&nbsp;tắm&nbsp;đi!&nbsp;Đừng&nbsp;nằm&nbsp;lên&nbsp;giường&nbsp;tớ.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đạp&nbsp;nhẹ&nbsp;vào&nbsp;chân&nbsp;Taehyung,&nbsp;mắt&nbsp;không&nbsp;rời&nbsp;khỏi&nbsp;màn&nbsp;hình.&nbsp;Taehyung&nbsp;vẫn&nbsp;nằm&nbsp;im&nbsp;không&nbsp;nhúc&nbsp;nhích.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Màn&nbsp;hình&nbsp;game&nbsp;Jimin&nbsp;cùng&nbsp;đồng&nbsp;đội&nbsp;đang&nbsp;tập&nbsp;kết&nbsp;Boss&nbsp;Hội,&nbsp;trong&nbsp;kênh&nbsp;thoại&nbsp;discord&nbsp;vẫn&nbsp;vang&nbsp;lên&nbsp;tiếng&nbsp;cười&nbsp;nói&nbsp;ồn&nbsp;ào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bất&nbsp;lực,&nbsp;Jimin&nbsp;mặc&nbsp;kệ&nbsp;cái&nbsp;xác&nbsp;ướt&nbsp;phía&nbsp;sau,&nbsp;cậu&nbsp;quay&nbsp;lại&nbsp;cuộc&nbsp;trò&nbsp;chuyện&nbsp;với&nbsp;hội&nbsp;bạn&nbsp;trong&nbsp;game.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Boss&nbsp;còn&nbsp;bao&nbsp;nhiêu&nbsp;máu?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;10%,&nbsp;đẩy&nbsp;hết&nbsp;đi!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Khi&nbsp;boss&nbsp;bị&nbsp;hạ&nbsp;gục,&nbsp;Jimin&nbsp;bắt&nbsp;đầu&nbsp;cày&nbsp;phó&nbsp;bản.&nbsp;Giữa&nbsp;lúc&nbsp;đó,&nbsp;Jimin&nbsp;nói&nbsp;vu&nbsp;vơ&nbsp;với&nbsp;Taehyung&nbsp;phía&nbsp;sau.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Khi&nbsp;nãy&nbsp;tớ&nbsp;được&nbsp;Jeon&nbsp;Jungkook&nbsp;đưa&nbsp;về&nbsp;đấy.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Taehyung&nbsp;vẫn&nbsp;nhắm&nbsp;mắt,&nbsp;giọng&nbsp;mệt&nbsp;mỏi&nbsp;đến&nbsp;mức&nbsp;gần&nbsp;như&nbsp;không&nbsp;có&nbsp;cảm&nbsp;xúc.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đãi&nbsp;ngộ&nbsp;công&nbsp;ty&nbsp;tốt&nbsp;thế&nbsp;cơ&nbsp;à.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Không,&nbsp;anh&nbsp;ta&nbsp;có&nbsp;việc&nbsp;gần&nbsp;đây,&nbsp;tiện&nbsp;nhờ&nbsp;tớ&nbsp;chỉ&nbsp;đường&nbsp;thôi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;À&nbsp;há.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;im&nbsp;lặng&nbsp;hai&nbsp;giây,&nbsp;tay&nbsp;vẫn&nbsp;đều&nbsp;đều&nbsp;đánh&nbsp;quái,&nbsp;rồi&nbsp;như&nbsp;chợt&nbsp;nhớ&nbsp;ra&nbsp;điều&nbsp;gì&nbsp;đó,&nbsp;cậu&nbsp;xoay&nbsp;người,&nbsp;không&nbsp;báo&nbsp;trước&nbsp;mà&nbsp;đạp&nbsp;thẳng&nbsp;vào&nbsp;người&nbsp;Taehyung&nbsp;một&nbsp;cái&nbsp;khiến&nbsp;cậu&nbsp;ta&nbsp;bật&nbsp;dậy&nbsp;kêu&nbsp;oai&nbsp;oái.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;CÚT&nbsp;ĐI&nbsp;TẮM!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Trong&nbsp;kênh&nbsp;Discord,&nbsp;giọng&nbsp;Kim&nbsp;Seokjin&nbsp;vang&nbsp;lên&nbsp;đầy&nbsp;tò&nbsp;mò.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Jeon&nbsp;Jungkook&nbsp;nào&nbsp;thế?&nbsp;Đối&nbsp;tượng&nbsp;mới&nbsp;à?&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;cười&nbsp;nhạt.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Đùa!&nbsp;Người&nbsp;ta&nbsp;là&nbsp;đại&nbsp;thần&nbsp;đấy!&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Khoảng&nbsp;tám&nbsp;giờ&nbsp;tối,&nbsp;sau&nbsp;khi&nbsp;game&nbsp;xong,&nbsp;Jimin&nbsp;mới&nbsp;nhận&nbsp;ra&nbsp;bụng&nbsp;mình&nbsp;đói&nbsp;cồn&nbsp;cào.&nbsp;Taehyung&nbsp;đã&nbsp;lăn&nbsp;ra&nbsp;ngủ&nbsp;từ&nbsp;lúc&nbsp;nào,&nbsp;để&nbsp;lại&nbsp;một&nbsp;đống&nbsp;hỗn&nbsp;độn&nbsp;và&nbsp;một&nbsp;cái&nbsp;mùi&nbsp;ẩm&nbsp;ẩm&nbsp;đáng&nbsp;ngờ.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;xỏ&nbsp;dép,&nbsp;định&nbsp;ra&nbsp;ngoài&nbsp;kiếm&nbsp;gì&nbsp;ăn&nbsp;thì&nbsp;điện&nbsp;thoại&nbsp;rung&nbsp;lên.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Là&nbsp;tin&nbsp;nhắn&nbsp;từ&nbsp;Jungkook.</span></p><p><em style=\"color: rgb(255, 255, 255);\">&quot;Xuống&nbsp;đây.&quot;</em></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;nhìn&nbsp;lại&nbsp;mình.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Ao&nbsp;thun&nbsp;rộng&nbsp;cổ&nbsp;đã&nbsp;giãn,&nbsp;quần&nbsp;short&nbsp;xám&nbsp;tro,&nbsp;tóc&nbsp;hơi&nbsp;rối&nbsp;như&nbsp;vừa&nbsp;bị&nbsp;gió&nbsp;thổi&nbsp;ngược.&nbsp;Jimin&nbsp;suy&nbsp;nghĩ&nbsp;vài&nbsp;giây,&nbsp;dù&nbsp;gì&nbsp;cũng&nbsp;ngoài&nbsp;phạm&nbsp;trù&nbsp;công&nbsp;việc,&nbsp;cậu&nbsp;vẫn&nbsp;quyết&nbsp;định&nbsp;đi&nbsp;xuống&nbsp;với&nbsp;bộ&nbsp;dạng&nbsp;đó.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Dưới&nbsp;cổng&nbsp;ký&nbsp;túc&nbsp;xá,&nbsp;Jungkook&nbsp;đứng&nbsp;dưới&nbsp;ánh&nbsp;đèn,&nbsp;khoác&nbsp;một&nbsp;chiếc&nbsp;blazer&nbsp;đen&nbsp;gọn&nbsp;gàng&nbsp;cùng&nbsp;chiếc&nbsp;áo&nbsp;thun&nbsp;cùng&nbsp;màu,&nbsp;dáng&nbsp;người&nbsp;tựa&nbsp;nhẹ&nbsp;vào&nbsp;xe,&nbsp;chỉnh&nbsp;chu&nbsp;đến&nbsp;mức&nbsp;gần&nbsp;như&nbsp;không&nbsp;thuộc&nbsp;về&nbsp;khung&nbsp;cảnh&nbsp;này.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;vừa&nbsp;xuất&nbsp;hiện,&nbsp;anh&nbsp;đã&nbsp;bước&nbsp;tới,&nbsp;đưa&nbsp;cho&nbsp;cậu&nbsp;một&nbsp;túi&nbsp;thức&nbsp;ăn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cảm&nbsp;ơn&nbsp;em&nbsp;đã&nbsp;chỉ&nbsp;đường.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;còn&nbsp;chưa&nbsp;kịp&nbsp;phản&nbsp;ứng,&nbsp;chưa&nbsp;kịp&nbsp;nói&nbsp;một&nbsp;câu&nbsp;khách&nbsp;sáo,&nbsp;Jungkook&nbsp;đã&nbsp;quay&nbsp;người,&nbsp;mở&nbsp;cửa&nbsp;xe&nbsp;rồi&nbsp;rời&nbsp;đi,&nbsp;để&nbsp;lại&nbsp;cậu&nbsp;đứng&nbsp;đó&nbsp;với&nbsp;túi&nbsp;đồ&nbsp;ăn&nbsp;trên&nbsp;tay&nbsp;và&nbsp;một&nbsp;đống&nbsp;suy&nbsp;nghĩ&nbsp;chưa&nbsp;kịp&nbsp;sắp&nbsp;xếp.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Chiếc&nbsp;xe&nbsp;nhanh&nbsp;chóng&nbsp;biến&nbsp;mất&nbsp;trong&nbsp;màn&nbsp;đêm&nbsp;còn&nbsp;vương&nbsp;hơi&nbsp;mưa.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;đứng&nbsp;nhìn&nbsp;theo&nbsp;một&nbsp;lúc&nbsp;lâu,&nbsp;rồi&nbsp;cúi&nbsp;xuống&nbsp;nhìn&nbsp;túi&nbsp;thức&nbsp;ăn,&nbsp;trong&nbsp;lòng&nbsp;âm&nbsp;thầm&nbsp;dựng&nbsp;lên&nbsp;cả&nbsp;một&nbsp;tượng&nbsp;đài&nbsp;vì&nbsp;lòng&nbsp;biết&nbsp;ơn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;thật&nbsp;sự&nbsp;muốn&nbsp;rơi&nbsp;nước&nbsp;mắt&nbsp;ngay&nbsp;lúc&nbsp;này,&nbsp;một&nbsp;buổi&nbsp;tối&nbsp;sau&nbsp;cơn&nbsp;mưa&nbsp;với&nbsp;cái&nbsp;bụng&nbsp;réo&nbsp;inh&nbsp;ỏi&nbsp;vì&nbsp;đói,&nbsp;một&nbsp;người&nbsp;đàn&nbsp;ông&nbsp;đẹp&nbsp;trai&nbsp;một&nbsp;cách&nbsp;lộng&nbsp;lẫy&nbsp;bước&nbsp;đến&nbsp;giải&nbsp;cứu&nbsp;cái&nbsp;bụng&nbsp;của&nbsp;cậu.&nbsp;Có&nbsp;trời&nbsp;mới&nbsp;biết&nbsp;cậu&nbsp;đang&nbsp;cảm&nbsp;động&nbsp;đến&nbsp;dường&nbsp;nào.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Cậu&nbsp;mang&nbsp;đồ&nbsp;ăn&nbsp;lên&nbsp;phòng,&nbsp;mở&nbsp;ra,&nbsp;bên&nbsp;trong&nbsp;là&nbsp;một&nbsp;hộp&nbsp;cháo&nbsp;hải&nbsp;sản&nbsp;còn&nbsp;nóng,&nbsp;mùi&nbsp;thơm&nbsp;lan&nbsp;ra&nbsp;ngay&nbsp;lập&nbsp;tức,&nbsp;là&nbsp;món&nbsp;cậu&nbsp;thích&nbsp;nhất.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Bao&nbsp;bì&nbsp;trông&nbsp;có&nbsp;vẻ&nbsp;được&nbsp;mua&nbsp;từ&nbsp;một&nbsp;quán&nbsp;ăn&nbsp;nhỏ&nbsp;nằm&nbsp;sâu&nbsp;trong&nbsp;con&nbsp;hẻm&nbsp;nhỏ&nbsp;sau&nbsp;trường.&nbsp;Quán&nbsp;ăn&nbsp;này&nbsp;hương&nbsp;vị&nbsp;rất&nbsp;ngon&nbsp;nhưng&nbsp;không&nbsp;nổi&nbsp;tiếng&nbsp;lắm,&nbsp;nơi&nbsp;mà&nbsp;địa&nbsp;chỉ&nbsp;cũng&nbsp;không&nbsp;được&nbsp;tìm&nbsp;thấy&nbsp;trên&nbsp;bản&nbsp;đồ,&nbsp;chỉ&nbsp;lưu&nbsp;truyền&nbsp;với&nbsp;sinh&nbsp;viên&nbsp;trường&nbsp;cậu.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;không&nbsp;rõ&nbsp;bằng&nbsp;cách&nbsp;nào&nbsp;Jungkook&nbsp;có&nbsp;thể&nbsp;tìm&nbsp;quán&nbsp;này.&nbsp;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Suy&nbsp;nghĩ&nbsp;đó&nbsp;trôi&nbsp;qua&nbsp;rất&nbsp;nhanh,&nbsp;bị&nbsp;cái&nbsp;bụng&nbsp;đói&nbsp;kéo&nbsp;đi&nbsp;mất.&nbsp;Cậu&nbsp;vừa&nbsp;ăn&nbsp;vừa&nbsp;lấy&nbsp;điện&nbsp;thoại&nbsp;ra,&nbsp;nhắn&nbsp;tin&nbsp;cho&nbsp;Jungkook.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Cảm&nbsp;ơn&nbsp;anh&nbsp;rất&nbsp;nhiều,&nbsp;vừa&nbsp;hay&nbsp;em&nbsp;đang&nbsp;tính&nbsp;đi&nbsp;ăn&nbsp;tối.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Khoảng&nbsp;một&nbsp;lúc&nbsp;sau,&nbsp;Jungkook&nbsp;gửi&nbsp;lại&nbsp;hai&nbsp;tin&nbsp;nhắn.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ăn&nbsp;ngon&nbsp;miệng.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Ngủ&nbsp;sớm&nbsp;nhé.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;chưa&nbsp;kịp&nbsp;trả&nbsp;lời,&nbsp;thì&nbsp;Jungkook&nbsp;nhắn&nbsp;thêm&nbsp;một&nbsp;câu&nbsp;nữa.</span></p><p><span style=\"color: rgb(255, 255, 255);\">&quot;Nếu&nbsp;còn&nbsp;đi&nbsp;trễ&nbsp;thêm&nbsp;một&nbsp;lần&nbsp;nữa,&nbsp;em&nbsp;không&nbsp;xong&nbsp;với&nbsp;tôi.&quot;</span></p><p><span style=\"color: rgb(255, 255, 255);\">Jimin&nbsp;suýt&nbsp;sặc.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Hôm&nbsp;đó&nbsp;Jimin&nbsp;đặc&nbsp;biệt&nbsp;nghe&nbsp;lời&nbsp;Jungkook.</span></p><p><span style=\"color: rgb(255, 255, 255);\">Mọi&nbsp;hôm&nbsp;là&nbsp;hai&nbsp;giờ&nbsp;sáng&nbsp;mới&nbsp;ngủ.&nbsp;Hôm&nbsp;nay&nbsp;phá&nbsp;lệ&nbsp;ngủ&nbsp;lúc&nbsp;một&nbsp;giờ&nbsp;năm&nbsp;mươi&nbsp;chín&nbsp;phút.</span></p>','PUBLISHED',725,4,'2026-06-04 21:15:12','2026-06-04 21:07:44','2026-07-06 07:14:01',0,20,3,7,'chuong-2-dao-hoa-cu-ty'),(138,22,'CHƯƠNG 3: HỮU BẬT ĐÀO HOA',3,'<p><em>&quot;Hữu&nbsp;Bật&nbsp;đi&nbsp;cùng&nbsp;Đào&nbsp;Hoa,&nbsp;ấy&nbsp;là&nbsp;lúc&nbsp;đóa&nbsp;hoa&nbsp;rực&nbsp;rỡ&nbsp;nhất&nbsp;giữa&nbsp;vạn&nbsp;trùng&nbsp;vây&nbsp;của&nbsp;những&nbsp;tình&nbsp;thân.&nbsp;Một&nbsp;kẻ&nbsp;vô&nbsp;tư&nbsp;đón&nbsp;nhận&nbsp;những&nbsp;ân&nbsp;tình&nbsp;bằng&nbsp;trái&nbsp;tim&nbsp;thuần&nbsp;khiết,&nbsp;chẳng&nbsp;hay&nbsp;mình&nbsp;đang&nbsp;khơi&nbsp;dậy&nbsp;cơn&nbsp;sóng&nbsp;ngầm&nbsp;của&nbsp;sự&nbsp;chiếm&nbsp;hữu&nbsp;từ&nbsp;một&nbsp;đôi&nbsp;mắt&nbsp;đứng&nbsp;trong&nbsp;bóng&nbsp;tối&nbsp;quyền&nbsp;uy.&quot;</em></p><p>Lời&nbsp;cảnh&nbsp;báo&nbsp;tối&nbsp;hôm&nbsp;qua&nbsp;của&nbsp;Jungkook,&nbsp;rốt&nbsp;cuộc&nbsp;cũng&nbsp;chỉ&nbsp;dừng&nbsp;lại&nbsp;ở&nbsp;mức&nbsp;độ&nbsp;tồn&nbsp;tại.</p><p>Sáng&nbsp;hôm&nbsp;sau,&nbsp;Jimin&nbsp;vẫn&nbsp;dậy&nbsp;trễ,&nbsp;lại&nbsp;còn&nbsp;trễ&nbsp;hơn&nbsp;mọi&nbsp;ngày.</p><p>Cậu&nbsp;bật&nbsp;dậy&nbsp;khi&nbsp;đồng&nbsp;hồ&nbsp;đã&nbsp;nhảy&nbsp;qua&nbsp;một&nbsp;con&nbsp;số&nbsp;đáng&nbsp;báo&nbsp;động,&nbsp;đầu&nbsp;óc&nbsp;còn&nbsp;chưa&nbsp;kịp&nbsp;tỉnh&nbsp;hẳn&nbsp;đã&nbsp;vơ&nbsp;đại&nbsp;quần&nbsp;áo&nbsp;và&nbsp;chạy&nbsp;thục&nbsp;mạng&nbsp;ra&nbsp;trạm&nbsp;xe&nbsp;buýt.</p><p>Khi&nbsp;Jimin&nbsp;lao&nbsp;tới&nbsp;sảnh&nbsp;công&nbsp;ty,&nbsp;thang&nbsp;máy&nbsp;dành&nbsp;cho&nbsp;nhân&nbsp;viên&nbsp;vừa&nbsp;kịp&nbsp;đóng&nbsp;lại&nbsp;ngay&nbsp;trước&nbsp;mắt.</p><p>Công&nbsp;ty&nbsp;không&nbsp;quá&nbsp;khắt&nbsp;khe&nbsp;về&nbsp;giờ&nbsp;giấc,