INSERT INTO `posts` VALUES (21,35,'Đúng là viết fic cuối cùng vẫn là vì bản thân. Ngồi đăng lại fic sang đây nhân tiện đọc lại vài đoạn cũ, chẳng khác gì đọc một cuốn nhật ký của mình. Từng cảm xúc ấy đã ấp ôm, an ủi mình biết bao nhiêu. ','PERSONAL','2026-06-10 09:03:08','2026-06-10 09:03:08',NULL,NULL),(23,84,'Cảm ơn bạn admin giỏi giang đã tạo ra web đọc truyện độc quyền cho các Bánh >w<','PERSONAL','2026-06-11 10:16:51','2026-06-11 10:16:51',NULL,NULL),(24,19,'Alo alo hehe hihi tui là chủ web nè. Thời gian này tuy bù đầu với khóa luận tốt nghiệp, đi làm nhưng chẳng hiểu sao tui lại có đủ năng lượng để vừa viết truyện vừa làm con web Abora này nữa. Tuy bận nhưng mà tui cũng vui lắm vì được mọi người ủng hộ rất nhiệt tình.\nCòn quả truyện Họa Tên Người Trên Mây Gió của tui là tui viết từ lúc tui học lớp 10, cái thời mới nhú nhìn nhìn đời toàn mấy màu hồng nên văn chương lai láng lắm. Sau bao năm bỏ xó con bé thì tui quên kha khá plot khúc sau rồi, cơ mà đọc được vài comment và tin nhắn của mấy bà thì tui đã lấy lại được động lực viết tiếp bé nó, chắc lúc đọc sẽ hơi đứt khúc tí nhưng mà hy vọng được mọi người đón nhận he.\nBộ Nhà Tù Toàn Cảnh trong tưởng tượng của tui nó cũng vĩ mô đẳng cấp nhưng mà khi viết ra thì lạ lắm huhu, cơ mà tui thích thằng ku này vô cùng, nên là tui sẽ cố gắng hoàn sớm nhất có thể nhe.','PERSONAL','2026-06-12 02:06:40','2026-06-12 02:06:40',NULL,NULL);
/*!40000 ALTER TABLE `posts` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `reading_histories`
--

DROP TABLE IF EXISTS `reading_histories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reading_histories` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `story_id` bigint NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'reading',
  `is_favorite` tinyint(1) NOT NULL DEFAULT '0',
  `last_read_chapter_id` bigint DEFAULT NULL,
  `last_read_position` int DEFAULT NULL,
  `last_read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `in_library` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_story` (`user_id`,`story_id`),
  KEY `fk_reading_histories_story` (`story_id`),
  KEY `fk_reading_histories_chapter` (`last_read_chapter_id`),
  KEY `idx_reading_histories_user_status` (`user_id`,`status`),
  KEY `idx_reading_histories_user_favorite` (`user_id`,`is_favorite`),
  CONSTRAINT `fk_reading_histories_chapter` FOREIGN KEY (`last_read_chapter_id`) REFERENCES `chapters` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_reading_histories_story` FOREIGN KEY (`story_id`) REFERENCES `stories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_reading_histories_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `reading_histories`
--

LOCK TABLES `reading_histories` WRITE;
/*!40000 ALTER TABLE `reading_histories` DISABLE KEYS */;
